/* GENERATED by tools/bundle.mjs from apps/*.html — do not edit. Rebuild after changing any app.
   Every app's MathLab.app() registration, so the daily mix can draw rounds from all of them. */

MathLab.app('line-lab', {
  emoji: '📈',
  title: 'Line Lab',
  tagline: 'Read a line, draw it, find where it hits the axes.',
  blurb: 'Gradient and intercept: read them, rearrange for them, draw the line on a grid.',

  build() {
  const { rnd, rndNonZero, pick, mathHTML, note } = MathLab;
  const L = Linear;
  const { Q, eq, neg, div, isZero, qHTML, qText, SLOPES } = L;

  const lineHTML = (d) => L.dispHTML(d);
  const pt = (x, y) => '(' + qText(x) + ', ' + qText(y) + ')';

  /** The gradient a slip produces, named — so feedback can say WHICH mistake it was. */
  function diagnoseGradient(got, m, c, written) {
    if (isZero(got) && eq(L.abs(m), 1)) {
      return { trap: 'implicit-one', why: (m.n < 0 ? '−x' : 'x') + ' means ' + qText(m) + ' × x. The gradient is ' + qText(m) + ', not 0.' };
    }
    if (written && eq(got, written) && !eq(written, m)) {
      return { trap: 'coefficient-as-gradient', why: 'The number in front of x only gives the gradient once y is on its own.' };
    }
    if (eq(got, neg(m))) return { trap: 'gradient-sign', why: 'Check the sign of the gradient: ' + (m.n < 0 ? 'this line goes downhill, so it is negative.' : 'this line goes uphill, so it is positive.') };
    if (eq(got, c) && !eq(c, m)) return { trap: 'm-c-swapped', why: 'You have the intercept there. The gradient is the number with x.' };
    if (isZero(m)) return { trap: 'flat-gradient', why: 'There is no x at all, so the line is flat: gradient 0.' };
    return { trap: 'gradient-other', why: 'The gradient is the number multiplying x once the line reads y = mx + c.' };
  }

  function diagnoseIntercept(got, m, c) {
    if (eq(got, neg(c))) return { trap: 'intercept-sign', why: 'Check the sign: the line crosses the y-axis at ' + qText(c) + '.' };
    if (!isZero(m) && eq(got, div(neg(c), m))) return { trap: 'intercept-x-axis', why: 'That is where it crosses the x-axis. The y-intercept is where x = 0.' };
    if (eq(got, m) && !eq(c, m)) return { trap: 'm-c-swapped', why: 'That is the gradient. The y-intercept is the number on its own.' };
    return { trap: 'intercept-other', why: 'Put x = 0: what is y? That is where it crosses the y-axis.' };
  }

  /* ---------------- explanations, with this question's own numbers ---------------- */

  const M = (h) => '<span class="m">' + h + '</span>';

  /** How to read m and c off a line already in y = … form. */
  function explainRead(e, m, c, shownHTML) {
    const std = lineHTML(L.layoutLine(e));
    const steps = [];
    if (isZero(m)) steps.push('There is no x-term at all: y is the same everywhere. Flat line, gradient <b>0</b>.');
    else steps.push('Line it up with ' + M('y = <i class="var">m</i>x + <i class="var">c</i>') + (shownHTML !== std ? ': ' + M(shownHTML) + ' is the same as ' + M(std) : ': ' + M(std)) + '.');
    if (eq(L.abs(m), 1)) steps.push(M(m.n < 0 ? '−x' : 'x') + ' means ' + M(qText(m) + ' × x') + ', so the gradient is <b>' + qHTML(m) + '</b> — not 0.');
    else if (!isZero(m)) steps.push('The number multiplying x is the gradient: <b>' + qHTML(m) + '</b>' + (m.d > 1 ? ' — up ' + m.n + ' for every ' + m.d + ' across' : '') + '.');
    steps.push(isZero(c) ? 'No number on its own, so it crosses the y-axis at <b>0</b> (through the origin).'
      : 'The number on its own is where it crosses the y-axis: <b>' + qHTML(c) + '</b>, the point ' + M(pt(0, c)) + '. Check: put x = 0 and y = ' + qText(c) + '.');
    return '<ol>' + steps.map((x) => '<li>' + x + '</li>').join('') + '</ol>';
  }

  /** Rearranging a·x + b·y = k into y = mx + c, every line shown. */
  function explainRearrange(e, shownHTML) {
    const a = L.coef(e, 'x'), b = L.coef(e, 'y');
    const steps = ['Start: ' + M(shownHTML)];
    steps.push('Keep the y-term on the left, move the rest across (each sign flips): ' + M(lineHTML({ L: [L.T(b, 'y')], R: [L.T(neg(a), 'x'), L.T(e.k)] })));
    if (!eq(b, 1)) steps.push('Divide EVERY term by ' + qHTML(b) + ': ' + M(lineHTML(L.layoutLine(e))));
    steps.push('Now read it: gradient ' + M(qHTML(L.gradient(e))) + ', y-intercept ' + M(qHTML(L.yIntercept(e))) + '.');
    return '<ol>' + steps.map((x) => '<li>' + x + '</li>').join('') + '</ol>';
  }

  /** Drawing from y = mx + c: start on the y-axis, then step with the gradient. */
  function explainDraw(e, m, c) {
    if (m === null) {
      const k = L.div(e.k, L.coef(e, 'x'));
      return 'Every point on ' + M(lineHTML(L.layoutLine(e))) + ' has x = ' + qText(k) + ', whatever y is: ' + M(pt(k, 0)) + ', ' + M(pt(k, 1)) + ', ' + M(pt(k, 2)) + ' … That is a straight up-and-down line through x = ' + qText(k) + '.';
    }
    if (isZero(m)) return 'Every point has y = ' + qText(c) + ': ' + M(pt(0, c)) + ', ' + M(pt(1, c)) + ' … a flat line at height ' + qText(c) + '.';
    const run = m.d, rise = m.n;
    const p2 = { x: Q(run), y: L.add(c, rise) };
    return '<ol><li>Start where it crosses the y-axis: ' + M(pt(0, c)) + '.</li>' +
      '<li>Gradient ' + M(qHTML(m)) + ' = ' + (rise < 0 ? 'down ' + -rise : 'up ' + rise) + ' for every ' + run + ' across' + (run === 1 ? '' : ' (the bottom of the fraction is the steps across)') + '.</li>' +
      '<li>From ' + M(pt(0, c)) + ' go ' + run + ' right and ' + (rise < 0 ? -rise + ' down' : rise + ' up') + ': ' + M(pt(p2.x, p2.y)) + '.</li>' +
      '<li>Join the two points and extend the line both ways.</li></ol>';
  }

  /* ---------------- 📖 worked example ---------------- */

  function workedRound() {
    const { eq: e0 } = L.mcLine({ frac: Math.random() < 0.5, cRange: 4 });
    const e = L.normal(e0);
    const m = L.gradient(e), c = L.yIntercept(e);
    const a = L.coef(e, 'x'), b = L.coef(e, 'y');
    const shown = lineHTML(L.layoutStd(e, ['x', 'y']));
    const xi = L.xIntercept(e);
    return {
      noScore: true,
      noHint: true,
      prompt: '📖 Watch one line go from equation to graph — tap for each step.',
      question: shown,
      mount(stage, submit) {
        const steps = [
          { html: lineHTML({ L: [L.T(b, 'y')], R: [L.T(neg(a), 'x'), L.T(e.k)] }), because: 'Get y on its own: move the x-term across, and its sign flips.' },
          ...(eq(b, 1) ? [] : [{ html: lineHTML(L.layoutLine(e)), because: 'Divide every term by ' + qText(b) + '.' }]),
          { html: 'gradient ' + qHTML(m) + ', y-intercept ' + qHTML(c), because: 'In y = mx + c: the number with x is the gradient, the number on its own is where it crosses the y-axis.' },
          { html: 'start at ' + pt(0, c), because: 'The y-intercept is a point ON the y-axis: x is 0 there.' },
          { html: 'next point ' + pt(Q(m.d), L.add(c, m.n)), because: 'Gradient ' + qText(m) + ': ' + (m.n < 0 ? 'down ' + -m.n : 'up ' + m.n) + ' for every ' + m.d + ' across.' },
          ...(xi && L.isInt(xi) && !isZero(xi) ? [{ html: 'check: crosses the x-axis at ' + pt(xi, 0), because: 'Put y = 0 in ' + shown.replace(/<[^>]+>/g, '') + ' and solve for x — it should be on your line.' }] : []),
          { html: 'join and extend', because: 'Two points make the line. A third (like the x-intercept) catches mistakes.' },
        ];
        MathLab.worked(stage, { steps, tryLevel: 1, onDone() {} });
        const grid = Grid.create(stage, {});
        grid.line(e, { cls: 'a', label: 'the line' });
        grid.point(0, L.num(c), { cls: 'given', label: pt(0, c) });
        submit(true);
      },
    };
  }

  /* ---------------- ① read it ---------------- */

  function readRound(frac) {
    const kind = pick(['mc', 'mc', 'cm', 'negx', 'negx', 'flat', 'origin']);
    let m, c;
    if (kind === 'negx') { m = Q(pick([-1, -1, 1])); c = rndNonZero(-7, 7); }
    else if (kind === 'flat') { m = Q(0); c = rndNonZero(-6, 6); }
    else if (kind === 'origin') { m = pick(frac ? SLOPES.frac : SLOPES.whole); c = 0; }
    else { m = pick(frac ? SLOPES.frac : SLOPES.whole); c = rnd(-7, 7); }
    c = Q(c);
    const e = L.lineMC(m, c);
    const constFirst = kind === 'cm' || (kind === 'negx' && Math.random() < 0.5);
    const shown = lineHTML(constFirst ? L.layoutFor(e, 'y', true) : L.layoutLine(e));

    const round = {
      prompt: 'What are the gradient and the y-intercept?',
      question: shown,
      solution: 'gradient ' + qHTML(m) + ', y-intercept ' + qHTML(c),
      explain: () => explainRead(e, m, c, shown),
      rightWhy: 'Gradient ' + qHTML(m) + ' (the number with x), y-intercept ' + qHTML(c) + ' (the number on its own).',
      hint: 'Line it up with y = <i class="var">m</i>x + <i class="var">c</i>. The number with x is the gradient; the number on its own is where it crosses the y-axis.',
      mount(stage, submit) {
        MathLab.fields(stage, {
          fields: [{ key: 'm', label: 'gradient', long: true }, { key: 'c', label: 'y-intercept', long: true }],
          onSubmit(v) {
            const gm = L.parseNumber(v.m), gc = L.parseNumber(v.c);
            const empty = Object.keys(v).filter((k) => !v[k]);
            if (empty.length) {
              note('unfinished', { what: 'one of gradient/intercept' });
              return { ok: false, why: 'Fill in both — the question asks for the gradient AND the intercept.', wrong: empty };
            }
            if (!gm || !gc) return { ok: false, why: 'I can\'t read that. Use a number like −2, 3/4 or 1.5.', wrong: [!gm ? 'm' : 'c'] };
            const okM = eq(gm, m), okC = eq(gc, c);
            if (okM && okC) { submit(true); return { ok: true, right: ['m', 'c'] }; }
            const why = [];
            if (!okM) { const d = diagnoseGradient(gm, m, c); note('trap', { trap: d.trap }); why.push(d.why); }
            if (!okC) { const d = diagnoseIntercept(gc, m, c); note('trap', { trap: d.trap }); why.push(d.why); }
            submit(false, 0, why.join(' '));
            return { ok: false, lock: true, why: '', wrong: [!okM && 'm', !okC && 'c'].filter(Boolean), right: [okM && 'm', okC && 'c'].filter(Boolean) };
          },
        });
      },
    };
    return round;
  }

  /* ---------------- ② rearrange first ---------------- */

  function rearrangeRound(frac) {
    const { eq: e0, m, c } = L.mcLine({ frac: frac || Math.random() < 0.5, cRange: 6 });
    let e = L.normal(e0);
    if (isZero(L.coef(e, 'y'))) return rearrangeRound(frac);
    if (Math.random() < 0.4) e = L.scale(e, -1);
    const a = L.coef(e, 'x'), b = L.coef(e, 'y'), k = e.k;
    const style = pick(['std', 'std', 'zero', 'by']);
    const disp = style === 'zero' ? L.layoutZero(e, ['x', 'y'])
      : style === 'by' ? { L: [L.T(b, 'y')], R: [L.T(k), L.T(neg(a), 'x')] }
      : L.layoutStd(e, ['x', 'y']);
    const steps = (isZero(a) ? '' : lineHTML({ L: [L.T(b, 'y')], R: [L.T(neg(a), 'x'), L.T(k)] }) + ', then ÷ ' + qHTML(b) + ': ') + lineHTML(L.layoutLine(e));

    return {
      prompt: 'Get <i class="var">y</i> on its own first. Gradient and y-intercept?',
      question: lineHTML(disp),
      explain: () => explainRearrange(e, lineHTML(disp)),
      rightWhy: 'Rearranged: ' + lineHTML(L.layoutLine(e)) + '.',
      solution: 'gradient ' + qHTML(m) + ', y-intercept ' + qHTML(c) + ' &nbsp;(' + steps + ')',
      hint: 'Move the x-term to the other side (its sign flips), then divide EVERY term by the number in front of y.',
      mount(stage, submit) {
        MathLab.fields(stage, {
          fields: [{ key: 'm', label: 'gradient', long: true }, { key: 'c', label: 'y-intercept', long: true }],
          onSubmit(v) {
            const empty = Object.keys(v).filter((key) => !v[key]);
            if (empty.length) {
              note('unfinished', { what: 'one of gradient/intercept' });
              return { ok: false, why: 'Fill in both.', wrong: empty };
            }
            const gm = L.parseNumber(v.m), gc = L.parseNumber(v.c);
            if (!gm || !gc) return { ok: false, why: 'Use a number like −2, 3/4 or 1.5.', wrong: [!gm ? 'm' : 'c'] };
            const okM = eq(gm, m), okC = eq(gc, c);
            if (okM && okC) { submit(true); return { ok: true, right: ['m', 'c'] }; }
            const why = [];
            if (!okM) {
              let d;
              if (eq(gm, neg(a)) && !eq(b, 1)) d = { trap: 'forgot-divide', why: 'You moved the x-term — now divide by ' + qText(b) + ' as well.' };
              else d = diagnoseGradient(gm, m, c, a);
              note('trap', { trap: d.trap }); why.push(d.why);
            }
            if (!okC) {
              let d;
              if (eq(gc, k) && !eq(b, 1)) d = { trap: 'forgot-divide', why: 'Divide the number by ' + qText(b) + ' too — every term.' };
              else d = diagnoseIntercept(gc, m, c);
              note('trap', { trap: d.trap }); why.push(d.why);
            }
            submit(false, 0, why.join(' '));
            return { ok: false, lock: true, wrong: [!okM && 'm', !okC && 'c'].filter(Boolean), right: [okM && 'm', okC && 'c'].filter(Boolean) };
          },
        });
      },
    };
  }

  /* ---------------- ③ draw it ---------------- */

  const lineThrough = (p, q) => {
    const a = q.y - p.y, b = p.x - q.x;
    return L.E({ x: a, y: b }, a * p.x + b * p.y);
  };

  function drawRound(target, prompt) {
    const { e, m, c, label } = target;
    return {
      prompt: prompt || 'Tap two points on this line. (Drag to adjust before you let go.)',
      question: label,
      solution: label,
      explain: () => explainDraw(e, m, c),
      rightWhy: 'Both your points make the equation true — so the line through them is this line.',
      noHint: false,
      hint: m === null ? 'Every point on this line has the same ' + (isZero(L.coef(e, 'y')) ? 'x' : 'y') + '.'
        : 'Start where it crosses the y-axis: (0, ' + qText(c) + '). Then the gradient ' + qText(m) + ' says how far up for each step across.',
      mount(stage, submit) {
        const grid = Grid.create(stage, {});
        const pick2 = Grid.picker(grid, { max: 2, line: true });
        const row = document.createElement('div');
        row.className = 'answer-row';
        row.innerHTML = '<button type="button">Check my line</button>';
        stage.appendChild(row);
        const why = document.createElement('p');
        why.className = 'why-line';
        stage.appendChild(why);
        const btn = row.querySelector('button');
        btn.addEventListener('click', () => {
          const pts = pick2.points();
          if (pts.length < 2) {
            note('unfinished', { what: 'one point' });
            why.className = 'why-line bad';
            why.innerHTML = 'Two points make a line — tap one more.';
            return;
          }
          pick2.stop();
          btn.disabled = true;
          const user = lineThrough(pts[0], pts[1]);
          if (L.sameLine(user, e)) {
            grid.line(e, { cls: 'good' });
            submit(true);
            return;
          }
          grid.line(e, { cls: 'ghost', dashed: true, label: 'the line' });
          let d;
          const um = L.gradient(user), uc = L.yIntercept(user);
          const onXAxisC = c && !isZero(c) && pts.some((p) => p.y === 0 && eq(Q(p.x), c));
          if (m === null || isZero(L.coef(e, 'y'))) d = { trap: 'vertical-line', why: label.replace(/<[^>]+>/g, '') + ' is vertical: every point has the same x.' };
          else if (isZero(m) && (um === null || !isZero(um))) d = { trap: 'flat-gradient', why: 'There is no x in it, so it is flat: every point has the same y.' };
          else if (onXAxisC) d = { trap: 'intercept-x-axis', why: 'You put ' + qText(c) + ' on the x-axis. The y-intercept sits on the y-axis: (0, ' + qText(c) + ').' };
          else if (um && eq(um, neg(m)) && !isZero(m)) d = { trap: 'gradient-sign', why: 'Your line slopes the wrong way. Gradient ' + qText(m) + (m.n < 0 ? ' goes DOWN' : ' goes UP') + ' from left to right.' };
          else if (um && eq(um, m)) d = { trap: 'intercept-wrong', why: 'Right steepness! But it must cross the y-axis at (0, ' + qText(c) + ').' };
          else if (uc && eq(uc, c)) d = { trap: 'gradient-wrong', why: 'Right start at (0, ' + qText(c) + '). Then for every ' + m.d + ' across, go ' + Math.abs(m.n) + (m.n < 0 ? ' down.' : ' up.') };
          else d = { trap: 'line-other', why: 'Start at (0, ' + qText(c) + ') on the y-axis, then use the gradient to find the next point.' };
          note('trap', { trap: d.trap });
          submit(false, 0, d.why);
        });
      },
    };
  }

  function mcTarget(frac) {
    const { eq: e, m, c } = L.mcLine({ frac });
    return { e, m, c, label: lineHTML(L.layoutLine(e)) };
  }

  function specialTarget() {
    const k = rndNonZero(-5, 5);
    const kind = pick(['vertical', 'horizontal', 'origin']);
    if (kind === 'vertical') { const e = L.vertical(k); return { e, m: null, c: null, label: lineHTML(L.layoutLine(e)) }; }
    if (kind === 'horizontal') { const e = L.horizontal(k); return { e, m: Q(0), c: Q(k), label: lineHTML(L.layoutLine(e)) }; }
    const m = pick(SLOPES.whole);
    const e = L.lineMC(m, 0);
    return { e, m, c: Q(0), label: lineHTML(L.layoutLine(e)) };
  }

  /* ---------------- ④ intercepts ---------------- */

  function interceptRound() {
    const origin = Math.random() < 0.15;
    if (origin) {
      const m = pick(SLOPES.whole);
      const e = L.normal(L.lineMC(m, 0));
      return {
        prompt: 'Tap where this line crosses the x-axis and where it crosses the y-axis.',
        question: lineHTML(L.layoutStd(e, ['x', 'y'])),
        solution: 'both are (0, 0) — it goes through the origin, so you need one more point to draw it',
        explain: 'Put y = 0: the x-term must be 0, so x = 0. Put x = 0: y = 0 too. Both intercepts are the origin — the same point — so to draw it you need a second point: pick x = 1 and work out y.',
        hint: 'Put y = 0 and solve for x. Then put x = 0 and solve for y. Something special happens here.',
        mount(stage, submit) { originMount(stage, submit, e); },
      };
    }
    const { eq: e, xInt, yInt } = L.interceptLine();
    const disp = Math.random() < 0.25 ? L.layoutZero(e, ['x', 'y']) : L.layoutStd(e, ['x', 'y']);
    const a = L.coef(e, 'x'), b = L.coef(e, 'y');
    const working = 'Put y = 0: ' + lineHTML({ L: [L.T(a, 'x')], R: [L.T(e.k)] }) + ', so x = ' + qHTML(xInt) + ' → ' + pt(xInt, 0) +
      '. Put x = 0: ' + lineHTML({ L: [L.T(b, 'y')], R: [L.T(e.k)] }) + ', so y = ' + qHTML(yInt) + ' → ' + pt(0, yInt) + '.';
    return {
      prompt: 'Tap the two points where this line crosses the axes.',
      question: lineHTML(disp),
      explain: '<ol><li>On the x-axis every point has y = 0. ' + working.split('. Put x = 0')[0] + '.</li><li>On the y-axis every point has x = 0. Put x = 0' + working.split('. Put x = 0')[1] + '</li><li>An intercept always has a 0 in it — it sits ON an axis.</li></ol>',
      solution: pt(xInt, 0) + ' and ' + pt(0, yInt),
      hint: 'On the x-axis y = 0. On the y-axis x = 0. Put each one in and solve.',
      mount(stage, submit) {
        const grid = Grid.create(stage, {});
        const pick2 = Grid.picker(grid, { max: 2, line: true });
        const row = document.createElement('div');
        row.className = 'answer-row';
        row.innerHTML = '<button type="button">Check</button>';
        stage.appendChild(row);
        const why = document.createElement('p');
        why.className = 'why-line';
        stage.appendChild(why);
        const btn = row.querySelector('button');
        btn.addEventListener('click', () => {
          const pts = pick2.points();
          if (pts.length < 2) {
            note('unfinished', { what: 'one intercept' });
            why.className = 'why-line bad';
            why.innerHTML = 'A line like this crosses BOTH axes — find the other one too.';
            return;
          }
          pick2.stop();
          btn.disabled = true;
          const want = [{ x: L.num(xInt), y: 0 }, { x: 0, y: L.num(yInt) }];
          const has = (w) => pts.some((p) => p.x === w.x && p.y === w.y);
          if (has(want[0]) && has(want[1])) {
            grid.line(e, { cls: 'good' });
            want.forEach((w) => grid.point(w.x, w.y, { cls: 'good' }));
            submit(true, undefined, working);
            return;
          }
          grid.line(e, { cls: 'ghost', dashed: true });
          want.forEach((w) => grid.point(w.x, w.y, { cls: 'good' }));
          let d;
          if (pts.some((p) => p.x === want[0].x && p.y === want[1].y && p.x !== 0 && p.y !== 0)) {
            d = { trap: 'intercepts-merged', why: 'You joined the two answers into one point ' + pt(xInt, yInt) + '. An intercept sits ON an axis, so one of its numbers is always 0: ' + pt(xInt, 0) + ' and ' + pt(0, yInt) + '.' };
          } else if (pts.some((p) => p.x === want[1].y && p.y === 0) && pts.some((p) => p.x === 0 && p.y === want[0].x)) {
            d = { trap: 'intercepts-swapped', why: 'Swapped: the x-intercept comes from putting y = 0. ' + working };
          } else if (pts.some((p) => (p.x === -want[0].x && p.y === 0 && p.x !== 0) || (p.x === 0 && p.y === -want[1].y && p.y !== 0))) {
            d = { trap: 'intercept-sign', why: 'Check the sign when you divide. ' + working };
          } else {
            d = { trap: 'intercept-other', why: working };
          }
          note('trap', { trap: d.trap });
          submit(false, 0, d.why);
        });
      },
    };
  }

  function originMount(stage, submit, e) {
    const grid = Grid.create(stage, {});
    const pick2 = Grid.picker(grid, { max: 2, line: true });
    const row = document.createElement('div');
    row.className = 'answer-row';
    row.innerHTML = '<button type="button">Check</button>';
    stage.appendChild(row);
    const why = document.createElement('p');
    why.className = 'why-line';
    stage.appendChild(why);
    row.querySelector('button').addEventListener('click', () => {
      const pts = pick2.points();
      const onLine = pts.filter((p) => L.satisfies(e, { x: Q(p.x), y: Q(p.y) }));
      const hasO = pts.some((p) => p.x === 0 && p.y === 0);
      if (pts.length === 1 && hasO) {
        why.className = 'why-line';
        why.innerHTML = 'Yes — both intercepts are the origin! One point can\'t make a line, so tap one more point on it.';
        return;
      }
      pick2.stop();
      row.querySelector('button').disabled = true;
      if (hasO && onLine.length === 2) {
        grid.line(e, { cls: 'good' });
        submit(true, undefined, 'Both intercepts are (0, 0), so a second point is needed to draw it.');
      } else {
        grid.line(e, { cls: 'ghost', dashed: true });
        note('trap', { trap: hasO ? 'origin-second-point' : 'intercept-other' });
        submit(false, 0, hasO ? 'Right about the origin. Your second point is not on the line — try x = 1.' : 'Put y = 0: x comes out 0 too. The line goes through the origin (0, 0).');
      }
    });
  }

  /* ---------------- ⑤ special lines ---------------- */

  function specialRound() {
    if (Math.random() < 0.5) return drawRound(specialTarget(), 'Tap two points on this line.');
    const k = rndNonZero(-6, 6);
    const kinds = [
      { key: 'v', label: 'Vertical — straight up and down', e: L.vertical(k) },
      { key: 'h', label: 'Horizontal — flat', e: L.horizontal(k) },
      { key: 'o', label: 'Slanted, through the origin', e: L.lineMC(pick(SLOPES.whole), 0) },
      { key: 's', label: 'Slanted, not through the origin', e: L.lineMC(pick(SLOPES.whole), k) },
    ];
    const target = pick(kinds);
    const why = {
      v: 'x = ' + qText(k) + ' means every point has x = ' + qText(k) + ' — whatever y is. That is a vertical line; it has no y = mx + c form.',
      h: 'y = ' + qText(k) + ' means every point has y = ' + qText(k) + '. Flat: gradient 0.',
      o: 'No number on its own, so when x = 0, y = 0: it goes through the origin.',
      s: 'It has an x-term (slanted) and a number on its own (misses the origin).',
    };
    return {
      prompt: 'What kind of line is this?',
      question: lineHTML(L.layoutLine(target.e)),
      solution: target.label,
      explain: '<ol><li>Only x, no y (x = number): vertical.</li><li>Only y, no x (y = number): horizontal, gradient 0.</li><li>An x-term and no number on its own: slanted, through the origin.</li><li>An x-term and a number on its own: slanted, crossing the y-axis at that number.</li></ol>',
      hint: 'Ask: which letters are in it? Is there a number on its own?',
      mount(stage, submit) {
        const opts = MathLab.shuffle(kinds.map((kd) => ({
          html: kd.label,
          ok: kd.key === target.key,
          trap: target.key === 'v' && kd.key === 'h' ? 'x-equals-horizontal' : 'line-kind',
          why: kd.key === target.key ? why[kd.key] : why[target.key],
        })));
        MathLab.choice(stage, {
          options: opts,
          onDone(misses) {
            const grid = Grid.create(stage, {});
            grid.line(target.e, { cls: 'good' });
            submit(misses === 0, undefined, why[target.key]);
          },
        });
      },
    };
  }

  const MIX = [
    () => readRound(false), () => rearrangeRound(false), () => drawRound(mcTarget(false)),
    () => interceptRound(), () => specialRound(),
  ];
  const SPICY = [() => readRound(true), () => rearrangeRound(true), () => drawRound(mcTarget(true))];

  return [
    { name: '📖 Worked example', make: workedRound },
    { name: '① Read it', make: () => readRound(false) },
    { name: '② Rearrange first', make: () => rearrangeRound(false) },
    { name: '③ Draw it', make: () => drawRound(mcTarget(Math.random() < 0.3)) },
    { name: '④ Intercepts', make: interceptRound },
    { name: '⑤ Special lines', make: specialRound },
    { name: 'Mixed', make: () => pick(MIX)() },
    { name: '🌶 Spicy', make: () => pick(SPICY)() },
  ];
  },
});

MathLab.app('crossing', {
  emoji: '✖️',
  title: 'Crossing Point',
  tagline: 'Two lines, one point that works for both.',
  blurb: 'Solve a pair by graphing. Intercept or intersection? One, none or infinitely many?',

  build() {
  const { rnd, pick, shuffle, note } = MathLab;
  const L = Linear;
  const { Q, eq, qText, isZero } = L;

  const ORDER = ['x', 'y'];
  const pt = (p) => '(' + qText(p.x) + ', ' + qText(p.y) + ')';
  const asQ = (p) => ({ x: Q(p.x), y: Q(p.y) });

  /** Show a line the way the worksheets do — sometimes y = mx + c, sometimes ax + by = c. */
  function shown(e, how = pick(['mc', 'mc', 'std', 'std', 'zero', 'cm'])) {
    if (how === 'mc') return L.dispHTML(L.layoutLine(e));
    if (how === 'cm') return L.dispHTML(L.layoutFor(e, 'y', true) || L.layoutLine(e));
    const n = L.normal(e);
    const sc = L.scale(n, pick([1, 1, -1]));
    return L.dispHTML(how === 'zero' ? L.layoutZero(sc, ORDER) : L.layoutStd(sc, ORDER));
  }

  function eqsBlock(stage, a, b) {
    const box = document.createElement('div');
    box.className = 'eqs';
    box.innerHTML = '<div class="eqn a"><span class="tag">A</span>' + a + '</div><div class="eqn b"><span class="tag">B</span>' + b + '</div>';
    stage.appendChild(box);
  }

  function checks(e1, e2, p) {
    return '<div class="checks">' + L.checkHTML(e1, asQ(p), ORDER, 'A') + L.checkHTML(e2, asQ(p), ORDER, 'B') + '</div>';
  }

  function addHTML(stage, html) {
    const d = document.createElement('div');
    d.innerHTML = html;
    stage.appendChild(d);
    return d;
  }

  /** Intercepts of a line that land on whole grid points inside ±6. */
  function intercepts(e, name) {
    const out = [];
    const xi = L.xIntercept(e), yi = L.yIntercept(e);
    if (xi && L.isInt(xi) && Math.abs(xi.n) <= 6) out.push({ x: L.num(xi), y: 0, what: 'where line ' + name + ' crosses the x-axis', trap: 'intercept-vs-intersection' });
    if (yi && L.isInt(yi) && Math.abs(yi.n) <= 6) out.push({ x: 0, y: L.num(yi), what: 'where line ' + name + ' crosses the y-axis', trap: 'intercept-vs-intersection' });
    return out;
  }

  function judgeTap(p, e1, e2, sol) {
    const P = asQ(p);
    if (eq(P.x, sol.x) && eq(P.y, sol.y)) return null;
    const ints = [...intercepts(e1, 'A'), ...intercepts(e2, 'B')];
    const hit = ints.find((i) => i.x === p.x && i.y === p.y);
    if (hit) return { trap: 'intercept-vs-intersection', why: 'That is ' + hit.what + ' — an intercept. The answer is where the two LINES meet each other.' };
    const onA = L.satisfies(e1, P), onB = L.satisfies(e2, P);
    if (onA || onB) return { trap: 'one-line-only', why: pt(p) + ' is on line ' + (onA ? 'A' : 'B') + ' but not on line ' + (onA ? 'B' : 'A') + '. It has to work for both.' };
    if (p.x === L.num(sol.y) && p.y === L.num(sol.x)) return { trap: 'coordinates-swapped', why: 'x first, then y: across, then up.' };
    return { trap: 'crossing-other', why: 'Follow both lines to where they meet.' };
  }

  const ptQ = (x, y) => '(' + qText(x) + ', ' + qText(y) + ')';
  const lineHTML = (d) => L.dispHTML(d);

  /** Working for "where does this line cross the y-axis / x-axis" — with this line's numbers. */
  function axisWork(e, axis) {
    const a = L.coef(e, 'x'), b = L.coef(e, 'y');
    if (axis === 'y') {
      const v = L.yIntercept(e);
      return 'Put x = 0: ' + lineHTML({ L: [L.T(b, 'y')], R: [L.T(e.k)] }) + ', so y = ' + L.qHTML(v) + ' → ' + ptQ(0, v);
    }
    const v = L.xIntercept(e);
    return 'Put y = 0: ' + lineHTML({ L: [L.T(a, 'x')], R: [L.T(e.k)] }) + ', so x = ' + L.qHTML(v) + ' → ' + ptQ(v, 0);
  }

  const EXPLAIN_CROSS = '<ol><li>Each line is every point that makes its equation true.</li>' +
    '<li>The crossing is the one point on BOTH lines — so it makes BOTH equations true. That pair is the solution.</li>' +
    '<li>An intercept is different: where ONE line meets an axis. It always has a 0 in it.</li>' +
    '<li>Always check the crossing in both equations.</li></ol>';

  /* ---------------- ① step by step: build both lines, then cross ---------------- */

  function guidedRound() {
    const { e1, e2, sol } = L.graphPair({});
    const m1 = L.gradient(e1), c1 = L.yIntercept(e1);
    const B = L.scale(L.normal(e2), pick([1, -1]));
    const xiB = L.xIntercept(e2);
    const useXInt = xiB && L.isInt(xiB) && Math.abs(xiB.n) <= 6 && !L.isZero(xiB);
    const a = lineHTML(L.layoutLine(e1)), b = lineHTML(L.layoutStd(B, ORDER));

    const phases = [
      { line: 0, ask: 'Line A: ' + a + '. Where does it cross the <b>y-axis</b>? Tap that point.',
        ok: (p) => p.x === 0 && eq(Q(p.y), c1),
        because: 'In y = mx + c the number on its own, ' + qText(c1) + ', is where it crosses the y-axis: ' + ptQ(0, c1) + '.',
        wrong: (p) => (p.y === 0 && eq(Q(p.x), c1) ? { trap: 'intercept-x-axis', why: 'That is on the x-axis. The y-intercept sits on the y-axis, where x = 0: ' + ptQ(0, c1) + '.' }
          : p.x === 0 && eq(Q(p.y), L.neg(c1)) ? { trap: 'intercept-sign', why: 'Check the sign: c is ' + qText(c1) + '.' }
          : { trap: 'intercept-other', why: 'On the y-axis x = 0. Put x = 0 into y = mx + c: y = c = ' + qText(c1) + '.' }) },
      { line: 0, ask: 'Now use the gradient ' + L.qHTML(m1) + ': from ' + ptQ(0, c1) + ' go ' + m1.d + ' right and ' + (m1.n < 0 ? -m1.n + ' down' : m1.n + ' up') + '. Tap that point.',
        ok: (p) => L.satisfies(e1, { x: Q(p.x), y: Q(p.y) }) && !(p.x === 0),
        because: 'Gradient ' + qText(m1) + ' = ' + (m1.n < 0 ? 'down ' + -m1.n : 'up ' + m1.n) + ' for every ' + m1.d + ' across, so ' + ptQ(m1.d, L.add(c1, m1.n)) + ' is on the line too.',
        wrong: (p) => (L.satisfies(e1, { x: Q(p.x), y: Q(-p.y + 2 * L.num(c1)) }) ? { trap: 'gradient-sign', why: 'Wrong direction: ' + (m1.n < 0 ? 'a negative gradient goes DOWN as you go right.' : 'a positive gradient goes UP as you go right.') }
          : { trap: 'gradient-wrong', why: 'Across first (' + m1.d + '), then ' + (m1.n < 0 ? 'down ' + -m1.n : 'up ' + m1.n) + '. Count the squares from ' + ptQ(0, c1) + '.' }) },
      { line: 1, ask: 'Line B: ' + b + '. Put <b>x = 0</b> — where does it cross the y-axis? Tap it.',
        ok: (p) => p.x === 0 && eq(Q(p.y), L.yIntercept(e2)),
        because: axisWork(B, 'y') + '.',
        wrong: (p) => (p.y === 0 ? { trap: 'intercepts-swapped', why: 'x = 0 is the y-axis (up and down). ' + axisWork(B, 'y') + '.' }
          : { trap: 'intercept-other', why: axisWork(B, 'y') + '.' }) },
      useXInt
        ? { line: 1, ask: 'Put <b>y = 0</b> in line B — where does it cross the x-axis? Tap it.',
          ok: (p) => p.y === 0 && eq(Q(p.x), xiB),
          because: axisWork(B, 'x') + '. Two points — line B is drawn.',
          wrong: (p) => (p.x === 0 ? { trap: 'intercepts-swapped', why: 'y = 0 is the x-axis (left to right). ' + axisWork(B, 'x') + '.' }
            : L.satisfies(e2, { x: Q(p.x), y: Q(p.y) }) ? { trap: 'intercept-other', why: 'That point IS on line B — but the x-intercept has y = 0. ' + axisWork(B, 'x') + '.' }
            : { trap: 'intercept-sign', why: axisWork(B, 'x') + '.' }) }
        : { line: 1, ask: 'Find one more point on line B: pick an x, work out y from ' + b + ', and tap it.',
          ok: (p) => L.satisfies(e2, { x: Q(p.x), y: Q(p.y) }) && p.x !== 0,
          because: 'It makes ' + b + ' true, so it is on line B. Two points — line B is drawn.',
          wrong: () => ({ trap: 'line-other', why: 'Put your x into ' + b + ' and solve for y. The gradient of B is ' + qText(L.gradient(e2)) + ', which helps.' }) },
      { line: 2, ask: 'Both lines are drawn. Tap where they <b>cross</b>.',
        ok: (p) => eq(Q(p.x), sol.x) && eq(Q(p.y), sol.y),
        because: ptQ(sol.x, sol.y) + ' is on both lines, so it makes both equations true:',
        wrong: (p) => judgeTap(p, e1, e2, sol) },
    ];

    return {
      prompt: 'Build both lines step by step, then find where they cross.',
      question: '',
      solution: ptQ(sol.x, sol.y),
      explain: () => '<ol><li>Line A, ' + a + ': start at the y-intercept ' + ptQ(0, c1) + ', then use the gradient ' + L.qHTML(m1) + ' for a second point.</li>' +
        '<li>Line B, ' + b + ': ' + axisWork(B, 'y') + (useXInt ? '; ' + axisWork(B, 'x') : '') + '.</li>' +
        '<li>Where they cross: ' + ptQ(sol.x, sol.y) + '.<div class="checks">' + checks(e1, e2, { x: L.num(sol.x), y: L.num(sol.y) }).replace(/^<div class="checks">|<\/div>$/g, '') + '</div></li></ol>',
      mount(stage, submit) {
        eqsBlock(stage, a, b);
        // the instruction sits ABOVE the grid: below it, on a phone, it is off-screen
        const status = addHTML(stage, '<p class="step-prompt"></p>').firstChild;
        const grid = Grid.create(stage, {});
        const row = addHTML(stage, '<div class="answer-row"><button type="button">Check</button></div>');
        const btn = row.querySelector('button');
        const why = addHTML(stage, '<p class="why-line"> </p>').firstChild;
        let at = 0, misses = 0, tries = 0, pk = null;
        const placed = [[], []];

        function start() {
          const ph = phases[at];
          status.innerHTML = '<span class="kind-blurb">Step ' + (at + 1) + ' of ' + phases.length + '</span>' + ph.ask;
          tries = 0;
          pk = Grid.picker(grid, { max: 1 });
          btn.hidden = false;
          btn.disabled = false;
        }

        function advance(p, ph) {
          pk.stop(); pk.clear();
          if (ph.line < 2) {
            placed[ph.line].push(p);
            grid.point(p.x, p.y, { cls: ph.line ? 'hot' : 'given', label: '(' + p.x + ', ' + p.y + ')' });
            if (placed[ph.line].length === 2) grid.line(ph.line ? e2 : e1, { cls: ph.line ? 'b' : 'a', label: ph.line ? 'B' : 'A' });
          }
          btn.hidden = true;
          const cont = addHTML(stage, '<div class="answer-row"><button type="button" class="continue">' + (at === phases.length - 1 ? 'Finish' : 'Continue →') + '</button></div>');
          cont.querySelector('button').addEventListener('click', () => {
            cont.remove();
            why.innerHTML = ' ';
            at++;
            if (at < phases.length) { start(); return; }
            submit(misses === 0, Math.max(6, 20 - 3 * misses), 'All five steps — built from the equations, not guessed.');
          });
        }

        btn.addEventListener('click', () => {
          const [p] = pk.points();
          const ph = phases[at];
          if (!p) { why.className = 'why-line bad'; why.innerHTML = 'Tap a point on the grid first.'; return; }
          if (ph.ok(p)) {
            why.className = 'why-line good';
            why.innerHTML = ph.because + (ph.line === 2 ? checks(e1, e2, p) : '');
            if (ph.line === 2) grid.point(p.x, p.y, { cls: 'good', label: '(' + p.x + ', ' + p.y + ')' });
            advance(p, ph);
            return;
          }
          misses++; tries++;
          const w = ph.wrong(p) || { trap: 'crossing-other', why: 'Not that one.' };
          note('trap', { trap: w.trap });
          why.className = 'why-line bad';
          if (tries >= 2) {
            // show it, explain it, move on — a third blind try teaches nothing
            const want = ph.line === 2 ? { x: L.num(sol.x), y: L.num(sol.y) }
              : at === 0 ? { x: 0, y: L.num(c1) }
              : at === 1 ? { x: m1.d, y: L.num(L.add(c1, m1.n)) }
              : at === 2 ? { x: 0, y: L.num(L.yIntercept(e2)) }
              : useXInt ? { x: L.num(xiB), y: 0 } : (() => { for (let x = 1; x <= 6; x++) { const y = L.div(L.sub(e2.k, L.mul(L.coef(e2, 'x'), x)), L.coef(e2, 'y')); if (L.isInt(y) && Math.abs(y.n) <= 6) return { x, y: y.n }; } return { x: 0, y: L.num(L.yIntercept(e2)) }; })();
            why.innerHTML = w.why + ' It is ' + '(' + want.x + ', ' + want.y + '). ' + ph.because;
            if (ph.line === 2) grid.point(want.x, want.y, { cls: 'good' });
            advance(want, ph);
            return;
          }
          why.innerHTML = w.why + ' Try again.';
          pk.clear();
        });

        start();
      },
    };
  }

  /* ---------------- spot the crossing (Mixed only) ---------------- */

  function findRound() {
    const { e1, e2, sol } = L.graphPair({});
    const a = shown(e1), b = shown(e2);
    return {
      prompt: 'Where do the lines cross? Tap the point.',
      question: '',
      solution: pt(sol),
      explain: EXPLAIN_CROSS,
      hint: 'Ignore where the lines hit the axes. Look for the one spot where blue and orange touch.',
      mount(stage, submit) {
        eqsBlock(stage, a, b);
        const grid = Grid.create(stage, {});
        grid.line(e1, { cls: 'a', label: 'A' });
        grid.line(e2, { cls: 'b', label: 'B' });
        const pk = Grid.picker(grid, { max: 1 });
        const row = addHTML(stage, '<div class="answer-row"><button type="button">That\'s it</button></div>');
        const why = addHTML(stage, '<p class="why-line"> </p>').firstChild;
        row.querySelector('button').addEventListener('click', () => {
          const [p] = pk.points();
          if (!p) { why.innerHTML = 'Tap a point on the grid first.'; return; }
          pk.stop();
          row.querySelector('button').disabled = true;
          const bad = judgeTap(p, e1, e2, sol);
          grid.point(L.num(sol.x), L.num(sol.y), { cls: 'good', label: pt(sol) });
          addHTML(stage, checks(e1, e2, { x: L.num(sol.x), y: L.num(sol.y) }));
          if (!bad) { submit(true, undefined, 'It works in both — that is what a solution is.'); return; }
          note('trap', { trap: bad.trap });
          submit(false, 0, bad.why);
        });
      },
    };
  }

  /* ---------------- ② draw both, then cross ---------------- */

  function drawRound() {
    const { e1, e2, sol } = L.graphPair({});
    const a = shown(e1, pick(['mc', 'std'])), b = shown(e2, pick(['mc', 'std', 'cm']));
    return {
      prompt: 'Draw both lines, then find where they cross.',
      question: '',
      solution: pt(sol),
      explain: () => '<ol><li>Line A: ' + a + ' — ' + axisWork(e1, 'y') + ', then use the gradient ' + L.qHTML(L.gradient(e1)) + '.</li>' +
        '<li>Line B: ' + b + ' — ' + axisWork(e2, 'y') + ', then the gradient ' + L.qHTML(L.gradient(e2)) + '.</li>' +
        '<li>They cross at ' + pt(sol) + ' — check it in both.</li></ol>',
      hint: 'For each line find two points — the intercepts work well — and tap them.',
      mount(stage, submit) {
        eqsBlock(stage, a, b);
        const status = addHTML(stage, '<p class="step-prompt"></p>').firstChild;
        const grid = Grid.create(stage, {});
        const row = addHTML(stage, '<div class="answer-row"><button type="button">Check</button></div>');
        const btn = row.querySelector('button');
        const why = addHTML(stage, '<p class="why-line"> </p>').firstChild;
        let misses = 0;
        let phase = 0;
        let pk = null;
        const lines = [e1, e2];

        function start() {
          if (phase < 2) {
            status.innerHTML = 'Line ' + (phase ? 'B' : 'A') + ': tap two points on it.';
            pk = Grid.picker(grid, { max: 2, line: true });
          } else {
            status.innerHTML = 'Now tap where they cross.';
            pk = Grid.picker(grid, { max: 1 });
          }
        }

        btn.addEventListener('click', () => {
          const pts = pk.points();
          if (phase < 2) {
            if (pts.length < 2) { why.className = 'why-line bad'; why.innerHTML = 'Two points make a line.'; note('unfinished', { what: 'one point' }); return; }
            const [p, q] = pts;
            const user = L.E({ x: q.y - p.y, y: p.x - q.x }, (q.y - p.y) * p.x + (p.x - q.x) * p.y);
            pk.stop(); pk.clear();
            const e = lines[phase];
            const ok = L.sameLine(user, e);
            grid.line(e, { cls: phase ? 'b' : 'a', label: phase ? 'B' : 'A' });
            if (!ok) {
              misses++;
              note('trap', { trap: 'draw-line' });
              why.className = 'why-line bad';
              why.innerHTML = 'Not quite — here is line ' + (phase ? 'B' : 'A') + '. ' +
                (L.gradient(e) ? 'It crosses the y-axis at ' + qText(L.yIntercept(e)) + ' with gradient ' + qText(L.gradient(e)) + '.' : '');
            } else {
              why.className = 'why-line good';
              why.innerHTML = 'Line ' + (phase ? 'B' : 'A') + ' ✓';
            }
            phase++;
            start();
            return;
          }
          const [p] = pts;
          if (!p) { why.innerHTML = 'Tap the crossing point.'; return; }
          pk.stop();
          btn.disabled = true;
          const bad = judgeTap(p, e1, e2, sol);
          grid.point(L.num(sol.x), L.num(sol.y), { cls: 'good', label: pt(sol) });
          addHTML(stage, checks(e1, e2, { x: L.num(sol.x), y: L.num(sol.y) }));
          if (bad) { misses++; note('trap', { trap: bad.trap }); }
          if (bad) submit(false, 0, bad.why);
          else submit(true, Math.max(6, 20 - 5 * misses), misses ? 'Crossing found — and now you have seen both lines.' : 'Both lines and the crossing — all yours.');
        });
        start();
      },
    };
  }

  /* ---------------- ③ intercept or intersection? ---------------- */

  function sortRound() {
    const { e1, e2, sol } = L.graphPair({});
    const cands = [
      { x: L.num(sol.x), y: L.num(sol.y), what: 'where the two lines cross' },
      ...intercepts(e1, 'A'), ...intercepts(e2, 'B'),
    ].filter((c, i, arr) => arr.findIndex((d) => d.x === c.x && d.y === c.y) === i);
    const target = Math.random() < 0.4 ? cands[0] : pick(cands);
    const labels = ['where the two lines cross', 'where line A crosses the x-axis', 'where line A crosses the y-axis',
      'where line B crosses the x-axis', 'where line B crosses the y-axis'];
    // a point can be two things at once (an intercept that is also the crossing)
    const isAlso = cands.filter((c) => c.x === target.x && c.y === target.y).map((c) => c.what);
    const opts = labels.map((lab) => ({
      html: lab[0].toUpperCase() + lab.slice(1),
      ok: isAlso.includes(lab),
      trap: 'intercept-vs-intersection',
      why: isAlso.includes(lab) ? ''
        : lab === labels[0] ? 'Where the lines cross, the point is on BOTH lines. This one is on an axis — one of its numbers is 0.'
        : 'Look again: which axis is it on (or none?), and whose line is it on?',
    }));
    return {
      prompt: 'What is the orange point?',
      question: '',
      explain: '<ol><li><b>Intercept</b>: where ONE line meets an axis. On the x-axis y = 0; on the y-axis x = 0 — so an intercept always has a 0 in it.</li>' +
        '<li><b>Intersection</b> (crossing): where the TWO lines meet. It is on both lines, so it makes both equations true.</li>' +
        '<li>Test a point: is one of its numbers 0? Is it on line A, line B, or both?</li></ol>',
      solution: pt(target) + ' is ' + isAlso.join(' and '),
      hint: 'On an axis, one of the numbers is 0. Where the lines cross, the point is on both of them.',
      mount(stage, submit) {
        eqsBlock(stage, shown(e1), shown(e2));
        const grid = Grid.create(stage, {});
        grid.line(e1, { cls: 'a', label: 'A' });
        grid.line(e2, { cls: 'b', label: 'B' });
        grid.point(target.x, target.y, { cls: 'hot', r: 11 });
        MathLab.choice(stage, {
          options: opts,
          onDone(misses) {
            addHTML(stage, checks(e1, e2, target));
            grid.say(pt(target));
            submit(misses === 0, undefined, pt(target) + ' is ' + isAlso.join(' and ') + '.');
          },
        });
      },
    };
  }

  /* ---------------- ④ how many solutions? ---------------- */

  function signal(e1, e2) {
    const r = L.solve2(e1, e2, ORDER);
    if (r.kind === 'one') {
      const m1 = L.gradient(e1), m2 = L.gradient(e2);
      const perp = m1 && m2 && eq(L.mul(m1, m2), -1);
      return 'Different gradients' + (m1 && m2 ? ' (' + qText(m1) + ' and ' + qText(m2) + ')' : '') +
        ', so they cross exactly once, at ' + pt(r.sol) + '.' + (perp ? ' (They meet at a right angle — still just one crossing.)' : '');
    }
    // scale ② so the x-terms match, then subtract — exactly what elimination would do
    const ax = L.coef(e1, 'x'), bx = L.coef(e2, 'x');
    const f = !isZero(bx) ? L.div(ax, bx) : L.div(L.coef(e1, 'y'), L.coef(e2, 'y'));
    const d = L.subEq(e1, L.scale(e2, f));
    return r.kind === 'none'
      ? 'Same gradient, different intercepts: parallel. The algebra agrees — make the x-terms match and subtract, and you get <b>0 = ' + qText(d.k) + '</b>, which is never true. No pair works.'
      : 'Rearrange both and they are the SAME line. Subtracting gives <b>0 = 0</b>, always true: every point on the line works.';
  }

  function countRound() {
    const roll = Math.random();
    let e1, e2, kind;
    if (roll < 0.34) ({ e1, e2, kind } = L.specialPair('none'));
    else if (roll < 0.62) ({ e1, e2, kind } = L.specialPair('infinite'));
    else if (roll < 0.8) {
      // perpendicular-looking pair: a classic wrong category
      const m = pick([Q(1), Q(2), Q(-1), Q(1, 2), Q(-2), Q(3)]);
      const x0 = rnd(-3, 3), y0 = rnd(-3, 3);
      const mp = L.div(-1, m);
      e1 = L.lineMC(m, L.sub(y0, L.mul(m, x0)));
      e2 = L.lineMC(mp, L.sub(y0, L.mul(mp, x0)));
      kind = 'one';
    } else ({ e1, e2 } = L.graphPair({}), kind = 'one');
    const answer = { one: 'Exactly one', none: 'None', infinite: 'Infinitely many' };
    const why = {
      one: { none: 'They are not parallel — different gradients always cross once.', infinite: 'Different gradients: they are not the same line, so they only share one point.' },
      none: { one: 'Rearrange both: same gradient, different intercept. Parallel lines never meet.', infinite: 'Same gradient, but they cross the y-axis at different places — two different parallel lines.' },
      infinite: { one: 'Rearrange both: they turn into the same line. Every point on it works.', none: 'Same gradient AND same intercept — that is one line written twice, not two parallel ones.' },
    };
    const traps = { 'one>none': 'parallel-one', 'infinite>none': 'coincident-none', 'none>infinite': 'parallel-coincident' };
    const a = shown(e1), b = shown(e2);
    return {
      prompt: 'How many solutions does this pair have?',
      question: '',
      solution: answer[kind],
      explain: '<ol><li>Rearrange both into y = mx + c.</li><li>Different gradients → the lines cross once → <b>exactly one</b> solution (even if they cross at a right angle).</li>' +
        '<li>Same gradient, different intercept → parallel, never meet → <b>no</b> solution. Algebra gives something false like 0 = 7.</li>' +
        '<li>Same gradient AND same intercept → the same line twice → <b>infinitely many</b>. Algebra gives 0 = 0.</li></ol>',
      hint: 'Get both into y = mx + c. Compare the gradients first, then the intercepts.',
      mount(stage, submit) {
        eqsBlock(stage, a, b);
        const opts = ['one', 'none', 'infinite'].map((k) => ({
          html: answer[k], ok: k === kind,
          trap: traps[k + '>' + kind] || 'count-solutions',
          why: k === kind ? '' : why[kind][k],
        }));
        MathLab.choice(stage, {
          options: opts,
          onDone(misses) {
            const grid = Grid.create(stage, {});
            grid.line(e1, { cls: 'a', label: 'A' });
            grid.line(e2, { cls: 'b', label: 'B', dashed: kind === 'infinite' });
            submit(misses === 0, undefined, signal(e1, e2));
          },
        });
      },
    };
  }

  /* ---------------- ⑤ does it work? ---------------- */

  function checkRound() {
    const { e1, e2, sol } = L.elimPair({ range: 6, maxCo: 5 });
    const kind = pick(['right', 'right', 'one', 'swap', 'sign']);
    let cand = sol;
    if (kind === 'one') {
      // another point on ① that is not on ②
      const a = L.coef(e1, 'x'), b = L.coef(e1, 'y');
      cand = { x: L.add(sol.x, b), y: L.sub(sol.y, a) };
    } else if (kind === 'swap') cand = { x: sol.y, y: sol.x };
    else if (kind === 'sign') cand = pick([{ x: L.neg(sol.x), y: sol.y }, { x: sol.x, y: L.neg(sol.y) }]);
    const works = L.satisfies(e1, cand) && L.satisfies(e2, cand);
    const onlyOne = !works && (L.satisfies(e1, cand) || L.satisfies(e2, cand));
    return {
      prompt: 'Is ' + pt(cand) + ' the solution of this pair?',
      question: '',
      solution: works ? 'Yes' : 'No — the solution is ' + pt(sol),
      explain: 'A solution of a pair must make BOTH equations true. Put x and y into each one: work out the left side, compare it with the right side. Equal both times → it is the solution. Equal in only one → it is just a point on that one line.',
      hint: 'Put x and y into BOTH equations. Do the two sides come out equal each time?',
      mount(stage, submit) {
        const box = document.createElement('div');
        box.className = 'eqs';
        box.innerHTML = '<div class="eqn a"><span class="tag">①</span>' + L.dispHTML(L.layoutStd(e1, ORDER)) + '</div>' +
          '<div class="eqn b"><span class="tag">②</span>' + L.dispHTML(L.layoutStd(e2, ORDER)) + '</div>';
        stage.appendChild(box);
        MathLab.choice(stage, {
          options: [
            { html: 'Yes — it works in both', ok: works, trap: onlyOne ? 'checked-one-only' : 'check-pair', why: onlyOne ? 'It works in one equation, not in the other. A solution has to work in BOTH.' : 'Put it in and compare both sides.' },
            { html: 'No', ok: !works, trap: 'check-pair', why: 'Put it in: both sides come out equal, in both equations.' },
          ],
          onDone(misses) {
            addHTML(stage, '<div class="checks">' + L.checkHTML(e1, cand, ORDER, '①') + L.checkHTML(e2, cand, ORDER, '②') + '</div>');
            submit(misses === 0, undefined, works ? 'Equal both times: that is a solution.' : 'Not equal every time, so not the solution. (It is ' + pt(sol) + '.)');
          },
        });
      },
    };
  }

  const MIX = [findRound, guidedRound, drawRound, sortRound, countRound, checkRound];

  return [
    { name: '① Step by step', make: guidedRound },
    { name: '② Draw both', make: drawRound },
    { name: '③ Intercept or crossing?', make: sortRound },
    { name: '④ How many solutions?', make: countRound },
    { name: '⑤ Does it work?', make: checkRound },
    { name: 'Mixed', make: () => pick(MIX)() },
  ];
  },
});

MathLab.app('two-equations', {
  emoji: '⚖️',
  ownHints: true,
  title: 'Two Equations',
  tagline: 'Substitute or eliminate — and finish with x AND y.',
  blurb: 'Solve a pair step by step. Every step offers the real mistakes; the round ends only with both answers checked.',

  build() {
  const { pick, shuffle, mathHTML, note } = MathLab;
  const L = Linear;
  const { qHTML, qText } = L;
  const ORDER = ['x', 'y'];

  function problem(kind) {
    if (kind === 'sub') {
      const p = L.subPair({});
      return { kind, e1: p.eS, e2: p.eO, sol: p.sol, show1: L.dispHTML(L.layoutFor(p.eS, p.solved)), show2: L.dispHTML(L.layoutStd(p.eO, ORDER)), p };
    }
    const p = L.elimPair(kind === 'spicy' ? { shape: 'both', range: 9, maxCo: 9 } : {});
    return { kind: 'elim', e1: p.e1, e2: p.e2, sol: p.sol, show1: L.dispHTML(L.layoutStd(p.e1, ORDER)), show2: L.dispHTML(L.layoutStd(p.e2, ORDER)), p };
  }

  function scriptFor(pr, method) {
    if (method === 'sub') return L.substitutionScript(pr.p.eS, pr.p.eO, pr.p.solved, pr.p.free);
    return L.eliminationScript(pr.e1, pr.e2, pr.p.target || pick(['x', 'y']));
  }

  /** The whole solution, every line with the reason it is allowed — the "How it works" panel. */
  function explainScript(pr, script, steps) {
    const lines = steps.filter((st) => st.kind !== 'pick').map((st) =>
      '<li><span class="m">' + st.writtenHTML + '</span><br>' + (st.because || '') + '</li>');
    const pickStep = steps.find((st) => st.kind === 'pick');
    const intro = script.method === 'substitution'
      ? 'Substitution: one equation already says what one letter equals, so put that into the other.'
      : 'Elimination: make one letter\'s terms the same size, then ' + (pickStep ? 'add or subtract the equations so that letter disappears.' : 'combine the equations so it disappears.');
    return intro + '<ol>' + lines.join('') + '<li>Check in both: <div class="checks">' +
      L.checkHTML(pr.e1, pr.sol, ORDER, '①') + L.checkHTML(pr.e2, pr.sol, ORDER, '②') + '</div></li></ol>';
  }

  function workedRound() {
    const kind = pick(['sub', 'elim']);
    const pr = problem(kind);
    const script = scriptFor(pr, kind === 'sub' ? 'sub' : 'elim');
    const steps = script.steps.map(L.present).filter((st) => st.kind !== 'pick' || true);
    return {
      noScore: true,
      noHint: true,
      prompt: '📖 Watch one being solved — tap for each step.',
      question: '',
      mount(stage, submit) {
        stage.innerHTML = '<div class="eqs"><div class="eqn a"><span class="tag">①</span>' + pr.show1 + '</div><div class="eqn b"><span class="tag">②</span>' + pr.show2 + '</div></div>';
        const items = steps.map((st) => {
          if (st.kind === 'pick') {
            const right = st.options.find((o) => o.ok);
            return { html: right.label, because: right.because || right.why };
          }
          return { html: (st.tag ? '<span class="kind-blurb">' + st.tag + '</span>' : '') + st.writtenHTML, because: st.because };
        });
        items.push({ html: 'x = ' + qHTML(pr.sol.x) + ', y = ' + qHTML(pr.sol.y), because: 'Both values — that is the answer. Check it:<div class="checks">' +
          L.checkHTML(pr.e1, pr.sol, ORDER, '①') + L.checkHTML(pr.e2, pr.sol, ORDER, '②') + '</div>' });
        MathLab.worked(stage, {
          title: script.method === 'substitution' ? 'Substitution' : 'Elimination',
          steps: items,
          tryLevel: kind === 'sub' ? 1 : 2,
        });
        submit(true);
      },
    };
  }

  function makeRound(mode) {
    const kind = mode === 'sub' ? 'sub' : mode === 'elim' ? 'elim' : mode === 'spicy' ? 'spicy'
      : pick(['sub', 'elim', 'elim']);
    const pr = problem(kind);
    const typed = mode === 'write';
    const offerChoice = mode === 'mixed' && pr.kind === 'sub';

    const round = {
      prompt: 'Solve the pair.',
      question: '',
      solution: 'x = ' + qHTML(pr.sol.x) + ', y = ' + qHTML(pr.sol.y),
      mount(stage, submit) {
        let misses = 0, stuckCount = 0, cur = null;
        const found = {};

        stage.innerHTML = `
          <div class="goal"><b>Goal</b><span class="slot" data-x>x = ?</span><span class="slot" data-y>y = ?</span></div>
          <ol class="working" data-working></ol>
          <p class="step-prompt" data-prompt></p>
          <div data-area></div>
          <div class="answer-row"><button type="button" class="ghost" data-stuck>Stuck?</button></div>
        `;
        const working = stage.querySelector('[data-working]');
        const promptEl = stage.querySelector('[data-prompt]');
        const area = stage.querySelector('[data-area]');
        const stuckBtn = stage.querySelector('[data-stuck]');

        const write = (tag, html, now = true) => {
          working.querySelectorAll('li').forEach((li) => li.classList.remove('now'));
          const li = document.createElement('li');
          if (now) li.className = 'now';
          li.innerHTML = (tag ? '<span class="tag">' + tag + '</span>' : '') + html;
          working.appendChild(li);
        };
        const goal = (v, val) => {
          found[v] = val;
          const s = stage.querySelector('[data-' + v + ']');
          if (s) { s.innerHTML = mathHTML(v) + ' = ' + qHTML(val) + ' ✓'; s.classList.add('done'); }
        };

        write('①', pr.show1, false);
        write('②', pr.show2, false);

        let script, steps, i = 0;

        function begin(method) {
          script = scriptFor(pr, method);
          steps = script.steps.map(L.present);
          round.explain = () => explainScript(pr, script, steps);
          i = 0;
          next();
        }

        function next() {
          area.innerHTML = '';
          if (i >= steps.length) return finish();
          const st = steps[i];
          promptEl.innerHTML = st.prompt + (st.showContext ? '<div class="eqn">' + st.context + '</div>' : '');
          const done = () => {
            if (st.kind === 'value') { write('', st.writtenHTML); goal(st.v, st.answer); }
            else if (st.kind !== 'pick') write(st.tag || '', st.writtenHTML);
            i++;
            next();
          };

          if (typed && st.kind !== 'pick') {
            const isValue = st.kind === 'value';
            let tries = 0;
            cur = MathLab.fields(area, {
              fields: [{ key: 'a', label: isValue ? mathHTML(st.v) + ' =' : '', long: false }],
              keys: isValue ? [] : ['x', 'y'],
              onSubmit(v) {
                if (!v.a) { note('unfinished', { what: 'empty line' }); return { ok: false, why: 'Write the line first.', wrong: ['a'] }; }
                let ok;
                if (isValue) {
                  const n = L.parseNumber(v.a);
                  if (!n) return { ok: false, why: 'Write a number, like −3 or 5/2.', wrong: ['a'] };
                  ok = L.eq(n, st.answer);
                } else {
                  const e = L.parseEquation(v.a);
                  if (!e) return { ok: false, why: 'I can\'t read that as an equation. It needs an = sign, e.g. 3x − 2y = 10.', wrong: ['a'] };
                  ok = L.equivalent(e, st.answer);
                  if (ok && st.mustMatch) {
                    const match = (f) => Object.entries(st.mustMatch).every(([k, q]) => L.eq(L.mul(L.coef(e, k), f), q));
                    ok = match(1) || match(-1);
                  }
                }
                if (ok) return { ok: true, why: 'Yes. ' + (st.because || ''), right: ['a'], next: done };
                tries++; misses++;
                note('trap', { trap: 'typed-' + st.kind });
                const hintTrap = st.options.find((o) => !o.ok && o.why);
                if (tries >= 2) return { ok: false, lock: true, why: 'This is the line: ' + st.writtenHTML + '<br>' + (st.because || ''), wrong: ['a'], next: done };
                return { ok: false, why: 'Not that. ' + (hintTrap ? 'Watch out: ' + hintTrap.why : 'Check each term.'), wrong: ['a'] };
              },
            });
            return;
          }

          cur = MathLab.choice(area, {
            options: shuffle(st.options.map((o) => ({ html: o.html, ok: o.ok, why: o.why, trap: o.trap }))),
            onMiss() { misses++; },
            onDone: done,
          });
        }

        stuckBtn.addEventListener('click', () => {
          stuckCount++;
          if (cur && cur.reveal) cur.reveal();
          else if (steps && steps[i]) {
            const st = steps[i];
            if (cur && cur.inputs) {
              const inp = Object.values(cur.inputs)[0];
              inp.value = st.kind === 'value' ? qText(st.answer) : L.dispText(st.layout ? st.layout(st.answer) : st.written || st.dispRight);
            }
          }
        });

        function finish() {
          stuckBtn.hidden = true;
          promptEl.innerHTML = 'Last step — write the answer to the question: <b>both</b> values.';
          let wrongTries = 0;
          MathLab.fields(area, {
            fields: [{ key: 'x', label: mathHTML('x') + ' =' }, { key: 'y', label: mathHTML('y') + ' =' }],
            submitLabel: 'Done',
            onSubmit(v) {
              const empty = ['x', 'y'].filter((k) => !v[k]);
              if (empty.length) {
                note('unfinished', { what: 'stopped at one value' });
                return { ok: false, why: 'You found ' + (empty.length === 1 ? (empty[0] === 'x' ? 'y' : 'x') : 'nothing yet') + ' — the question asks for x AND y.', wrong: empty };
              }
              const gx = L.parseNumber(v.x), gy = L.parseNumber(v.y);
              if (!gx || !gy) return { ok: false, why: 'Write numbers, like −3 or 5/2.', wrong: [!gx && 'x', !gy && 'y'].filter(Boolean) };
              const pair = { x: gx, y: gy };
              const okX = L.eq(gx, pr.sol.x), okY = L.eq(gy, pr.sol.y);
              if (!okX || !okY) {
                misses++;
                wrongTries++;
                note('trap', { trap: L.eq(gx, pr.sol.y) && L.eq(gy, pr.sol.x) ? 'answer-swapped' : 'answer-copy' });
                if (wrongTries >= 3) {
                  round.firstTry = false;
                  setTimeout(() => submit(false, 0, 'The values are in your working: x = ' + qHTML(pr.sol.x) + ', y = ' + qHTML(pr.sol.y) + '. Copy both into the answer.'), 200);
                  return { ok: false, lock: true, why: '', wrong: [!okX && 'x', !okY && 'y'].filter(Boolean) };
                }
                return { ok: false, why: 'Check it in both: <div class="checks">' + L.checkHTML(pr.e1, pair, ORDER, '①') + L.checkHTML(pr.e2, pair, ORDER, '②') + '</div>', wrong: [!okX && 'x', !okY && 'y'].filter(Boolean) };
              }
              settle(pair);
              return { ok: true, right: ['x', 'y'] };
            },
          });
        }

        function settle(pair) {
          const box = document.createElement('div');
          box.className = 'bridge';
          box.innerHTML = '<b>Check it — both equations</b><div class="checks">' +
            L.checkHTML(pr.e1, pair, ORDER, '①') + L.checkHTML(pr.e2, pair, ORDER, '②') + '</div>' +
            '<p class="process">' + (script.method === 'substitution' ? 'Substitution' : 'Elimination') + ' · ' + steps.length + ' steps' +
            (misses === 0 && stuckCount === 0 ? ' · every step yours ⭐️' : ' · finished it') + '</p>';
          stage.appendChild(box);
          round.firstTry = misses === 0 && stuckCount === 0;
          submit(true, Math.max(4, 20 - 3 * misses - 3 * stuckCount));
          const nextBtn = document.querySelector('[data-next]');
          if (nextBtn) nextBtn.scrollIntoView({ block: 'center', behavior: 'smooth' });
        }

        if (offerChoice) {
          promptEl.innerHTML = '① already says what ' + pr.p.solved + ' equals. Which way in?';
          let chosen = 'sub';
          cur = MathLab.choice(area, {
            options: [
              { html: 'Substitute ① into ②', ok: true, why: 'Quickest here: ① hands you ' + pr.p.solved + ' ready-made.' },
              { html: 'Line them up and eliminate', ok: true, why: 'Works too — ① just gets lined up as ax + by = c first.' },
            ],
            onDone: () => begin(chosen),
          });
          // both are right; the one she taps decides the method (the choice fires onDone later)
          area.querySelectorAll('button.option').forEach((b, k) => b.addEventListener('click', () => { chosen = k === 0 ? 'sub' : 'elim'; }));
        } else {
          begin(pr.kind === 'sub' ? 'sub' : 'elim');
        }
      },
    };
    return round;
  }

  return [
    { name: '📖 Worked example', make: workedRound },
    { name: '① Substitution', make: () => makeRound('sub') },
    { name: '② Elimination', make: () => makeRound('elim') },
    { name: 'Mixed', make: () => makeRound('mixed') },
    { name: '✍️ Write it yourself', make: () => makeRound('write') },
    { name: '🌶 Spicy', make: () => makeRound('spicy') },
  ];
  },
});

MathLab.app('story-solver', {
  emoji: '🧾',
  ownHints: true,
  title: 'Story Solver',
  tagline: 'Story → two equations → answer → does it make sense?',
  blurb: 'Word problems — tickets, coins, deals, shapes, ages, mixtures — turned into a pair of equations.',

  build() {
  const { pick, shuffle, mathHTML, note } = MathLab;
  const L = Linear;
  const { qNice, qHTML } = L;

  const fmtOf = (s) => (s.cents2 ? L.dispMoney : L.dispNice);
  const valFmt = (s, v) => (s.money && s.money.includes(v) ? (q) => L.money(q) : qNice);
  const layoutOf = (s, e) => e.layout || s.layout || ((x) => L.layoutStd(x, s.order));
  const optHTML = (s, e, o) => fmtOf(s)(o.disp || layoutOf(s, e)(o.eq));
  const rightHTML = (s, e) => optHTML(s, e, e.options.find((o) => o.ok));

  /* ---------- the shape picture for geometry stories ---------- */
  function figure(f) {
    const esc = (t) => String(t).replace(/<[^>]+>/g, '');
    if (!f) return '';
    if (f.type === 'rect' || f.type === 'para') {
      const skew = f.type === 'para' ? 40 : 0;
      return `<svg class="figure" viewBox="0 0 300 170" aria-hidden="true">
        <polygon class="shape" points="${40 + skew},30 ${260},30 ${260 - skew},130 40,130" />
        <text x="150" y="20" text-anchor="middle">${esc(f.top)}</text>
        <text x="150" y="155" text-anchor="middle">${esc(f.bottom)}</text>
        <text x="${30 + skew / 2}" y="85" text-anchor="end">${esc(f.left)}</text>
        <text x="${270 - skew / 2}" y="85">${esc(f.right)}</text>
      </svg>`;
    }
    if (f.type === 'tri') {
      const [nA, nB, nC] = f.names || ['', '', ''];
      return `<svg class="figure" viewBox="0 0 300 200" aria-hidden="true">
        <polygon class="shape" points="40,170 150,25 260,170" />
        ${f.equalSides ? '<line class="tick" x1="88" y1="92" x2="102" y2="102"/><line class="tick" x1="198" y1="102" x2="212" y2="92"/>' : ''}
        <text x="150" y="62" text-anchor="middle">${esc(f.a)}°</text>
        <text x="62" y="160">${esc(f.b)}°</text>
        <text x="238" y="160" text-anchor="end">${esc(f.c)}°</text>
        <text x="150" y="16" text-anchor="middle">${nA}</text>
        <text x="26" y="188">${nB}</text>
        <text x="274" y="188" text-anchor="end">${nC}</text>
      </svg>`;
    }
    if (f.type === 'tri-sides') {
      const [a, b, c] = f.sides.map(esc);
      return `<svg class="figure" viewBox="0 0 300 200" aria-hidden="true">
        <polygon class="shape" points="40,170 150,30 260,170" />
        <text x="82" y="92" text-anchor="end">${a}</text>
        <text x="218" y="92">${b}</text>
        <text x="150" y="192" text-anchor="middle">${c}</text>
      </svg>`;
    }
    return '';
  }

  const niceStep = (range, ticks = 6) => {
    const raw = range / ticks;
    const p = 10 ** Math.floor(Math.log10(raw));
    for (const m of [1, 2, 2.5, 5, 10]) if (m * p >= raw) return m * p;
    return 10 * p;
  };

  function costGraph(stage, s) {
    const g = s.graph;
    const xMax = g.nStar * 2;
    const yAt = (ln, x) => L.num(ln.f) + L.num(ln.r) * x;
    const yMaxRaw = Math.max(...g.lines.map((ln) => yAt(ln, xMax)));
    const xStep = niceStep(xMax, 8), yStep = niceStep(yMaxRaw, 8);
    const grid = Grid.create(stage, {
      xMin: 0, xMax: Math.ceil(xMax / xStep) * xStep, yMin: 0, yMax: Math.ceil(yMaxRaw / yStep) * yStep,
      xStep, yStep, xName: g.L, yName: 'c', firstQuadrant: true, labelEvery: 2,
    });
    g.lines.forEach((ln, k) => {
      grid.line(L.E({ c: 1, [g.L]: L.neg(ln.r) }, ln.f), { cls: k ? 'b' : 'a', label: ln.name.replace(/^the /, ''), vars: [g.L, 'c'] });
    });
    grid.point(g.nStar, L.num(g.cStar), { cls: 'good', label: g.nStar + ' ' + g.unit });
    grid.say('Below ' + g.nStar + ' the lower line is the cheaper deal; above it, the other one.');
  }

  const checksFor = (s) => s.eqs.map((e, i) => (e.layout || s.layout
    ? L.checkDispHTML(layoutOf(s, e)(e.eq), s.sol, s.eqs.length > 1 ? (i ? '②' : '①') : '', s.cents2 ? L.qMoney : qNice)
    : L.checkHTML(e.eq, s.sol, s.order, s.eqs.length > 1 ? (i ? '②' : '①') : '', s.cents2 ? L.qMoney : qNice))).join('');

  /** How to get from the pair to the values — the step most likely to be skipped on paper. */
  function solveTip(s) {
    if (s.eqs.length === 1) return '<br>One letter, one equation: collect the terms, then divide.';
    const [e1, e2] = s.eqs.map((e) => e.eq);
    const [u, v] = s.order;
    const solvedFor = [e1, e2].find((e) => Object.keys(e.co).some((k) => L.eq(L.coef(e, k), 1) && Object.keys(e.co).filter((j) => !L.isZero(L.coef(e, j))).length <= 2));
    return '<br>' + (s.layout ? 'Both equations say what c is, so set them equal: the costs are the same where the right-hand sides are equal.'
      : solvedFor ? 'One equation is easy to rearrange for one letter — substitute it into the other.'
      : 'Make the ' + u + '-terms (or the ' + v + '-terms) the same size, then subtract or add to make that letter disappear.');
  }

  /** The whole story, worked: kind, letters, each equation with its reason, solving, answer. */
  function explainStory(s) {
    const items = [
      '<b>Kind:</b> ' + Stories.KINDS[s.family].label + ' — ' + Stories.KINDS[s.family].blurb.toLowerCase(),
      '<b>Letters:</b> ' + s.letters.map((l) => mathHTML(l.v) + ' = ' + l.means).join('; '),
      ...s.eqs.map((e, i) => '<span class="m">' + rightHTML(s, e) + '</span><br>' + e.because),
      '<b>Solve:</b> ' + s.letters.map((l) => mathHTML(l.v) + ' = ' + valFmt(s, l.v)(s.sol[l.v])).join(', ') + solveTip(s) + '<div class="checks">' + checksFor(s) + '</div>',
    ];
    if (s.derived) items.push(s.derived.map((d) => d.label + ' = ' + d.html + ' = ' + qNice(d.value(s.sol))).join(', '));
    if (s.final && s.final.value) items.push(s.final.prompt.replace(/<[^>]+>/g, '') + ' ' + qNice(s.final.value) + ' ' + s.final.unit + (s.final.because ? ' — ' + s.final.because : ''));
    if (s.final && s.final.options) items.push(s.final.prompt + ' <b>' + s.final.options.find((o) => o.ok).label + '</b>');
    items.push('<b>Answer:</b> ' + s.sentence);
    return '<ol>' + items.map((x) => '<li>' + x + '</li>').join('') + '</ol>';
  }

  function workedRound() {
    const s = Stories.make();
    return {
      noScore: true,
      noHint: true,
      prompt: '📖 Watch one being solved — tap for each step.',
      question: '',
      mount(stage, submit) {
        stage.innerHTML = '<p class="story">' + s.text + '</p>' + figure(s.figure);
        const steps = [
          { html: Stories.KINDS[s.family].label, because: 'What kind is it? ' + Stories.KINDS[s.family].blurb },
          { html: s.letters.map((l) => mathHTML(l.v) + ' = ' + l.means).join('<br>'), because: 'Say exactly what each letter stands for — a number of things, not the things.' },
          ...s.eqs.map((e) => ({ html: rightHTML(s, e), because: e.because })),
          { html: s.letters.map((l) => mathHTML(l.v) + ' = ' + valFmt(s, l.v)(s.sol[l.v])).join(', '), because: solveTip(s).replace('<br>', '') + '<div class="checks">' + checksFor(s) + '</div>' },
        ];
        if (s.derived) steps.push({ html: s.derived.map((d) => d.label + ': ' + qNice(d.value(s.sol))).join(', '), because: 'The question asked for every one of them.' });
        if (s.final && s.final.value) steps.push({ html: qNice(s.final.value) + ' ' + s.final.unit, because: (s.final.because || s.final.prompt) });
        if (s.final && s.final.options) steps.push({ html: s.final.options.find((o) => o.ok).label, because: 'Answer the question asked: it wants a decision.' });
        steps.push({ html: s.sentence, because: 'Does it make sense? Whole numbers of things, nothing negative, and it fits the story.' });
        MathLab.worked(stage, { steps, tryLevel: 1 });
        submit(true);
      },
    };
  }

  /* ---------- one round ---------- */

  function makeRound(opts) {
    const s = Stories.make(opts.family ? pick([].concat(opts.family)) : undefined);
    const typed = !!opts.typed;

    const round = {
      prompt: '',
      question: '',
      solution: s.sentence,
      explain: () => explainStory(s),
      mount(stage, submit) {
        let misses = 0, stuck = 0, cur = null;
        stage.innerHTML = `
          <p class="story">${s.text}</p>
          ${figure(s.figure)}
          <div class="letters" data-letters hidden></div>
          <ol class="working" data-working></ol>
          <p class="step-prompt" data-prompt></p>
          <div data-area></div>
          <div class="answer-row"><button type="button" class="ghost" data-stuck>Stuck?</button></div>`;
        const lettersEl = stage.querySelector('[data-letters]');
        const working = stage.querySelector('[data-working]');
        const promptEl = stage.querySelector('[data-prompt]');
        const area = stage.querySelector('[data-area]');
        const stuckBtn = stage.querySelector('[data-stuck]');

        const write = (tag, html) => {
          working.querySelectorAll('li').forEach((li) => li.classList.remove('now'));
          const li = document.createElement('li');
          li.className = 'now';
          li.innerHTML = (tag ? '<span class="tag">' + tag + '</span>' : '') + html;
          working.appendChild(li);
        };

        const steps = [];
        if (opts.kind) steps.push(kindStep);
        steps.push(lettersStep);
        if (typed) steps.push(typedEquations);
        else s.eqs.forEach((e, k) => steps.push(() => eqStep(e, k)));
        if (!opts.kindOnly) {
          steps.push(solveStep);
          if (s.derived) steps.push(derivedStep);
          if (s.final) steps.push(finalStep);
        }
        let at = 0;
        const next = () => {
          area.innerHTML = '';
          cur = null;
          if (at >= steps.length) return settle();
          steps[at++]();
        };

        stuckBtn.addEventListener('click', () => {
          stuck++;
          if (cur && cur.reveal) cur.reveal();
          else if (cur && cur.fill) cur.fill();
        });

        /* --- which kind of problem? --- */
        function kindStep() {
          promptEl.innerHTML = 'Before any maths: what kind of problem is this?';
          const others = shuffle(Object.keys(Stories.KINDS).filter((k) => k !== s.family)).slice(0, 3);
          const options = shuffle([s.family, ...others]).map((k) => ({
            html: Stories.KINDS[k].label + '<span class="kind-blurb">' + Stories.KINDS[k].blurb + '</span>',
            ok: k === s.family,
            trap: 'schema',
            why: k === s.family ? Stories.KINDS[k].blurb : 'Look at what the story gives you: ' + Stories.KINDS[s.family].blurb.toLowerCase(),
          }));
          cur = MathLab.choice(area, { options, onMiss: () => misses++, onDone: next });
        }

        /* --- name the unknowns (given: the reversal error starts with fuzzy letters) --- */
        function lettersStep() {
          lettersEl.hidden = false;
          lettersEl.innerHTML = s.letters.map((l) => '<span>' + mathHTML(l.v) + ' = ' + l.means + '</span>').join('') +
            (s.derived ? s.derived.filter((d) => d.html !== '<i class="var">' + s.letters[0].v + '</i>')
              .map((d) => '<span>' + d.label + ' = ' + d.html + '</span>').join('') : '');
          next();
        }

        /* --- pick each equation --- */
        function eqStep(e, k) {
          promptEl.innerHTML = e.prompt;
          const options = shuffle(e.options.map((o) => ({ html: optHTML(s, e, o), ok: o.ok, why: o.ok ? e.because : o.why, trap: o.trap })));
          cur = MathLab.choice(area, {
            options,
            onMiss: () => misses++,
            onDone: () => { write(k ? '②' : '①', rightHTML(s, e)); next(); },
          });
        }

        /* --- write both equations yourself --- */
        function typedEquations() {
          promptEl.innerHTML = 'Write ' + (s.eqs.length > 1 ? 'two equations' : 'an equation') + ' for the story, using the letters above.';
          const vars = [...new Set(s.letters.map((l) => l.v))];
          let tries = 0;
          const flds = s.eqs.map((e, k) => ({ key: 'e' + k, label: k ? '②' : '①' }));
          cur = MathLab.fields(area, {
            fields: flds,
            keys: vars,
            onSubmit(v) {
              const empty = flds.filter((f) => !v[f.key]).map((f) => f.key);
              if (empty.length) { note('unfinished', { what: 'one equation' }); return { ok: false, why: 'Two unknowns need two equations.', wrong: empty }; }
              const parsed = flds.map((f) => L.parseEquation(v[f.key]));
              const unread = flds.filter((f, i) => !parsed[i]).map((f) => f.key);
              if (unread.length && ++tries < 3) return { ok: false, why: 'I can\'t read that. An equation needs an = sign, like 2a + 3c = 50.', wrong: unread };
              const matched = parsed.map((p) => (p ? s.eqs.findIndex((e) => L.equivalent(p, e.eq)) : -1));
              const covered = new Set(matched.filter((m) => m >= 0));
              if (covered.size === s.eqs.length) {
                s.eqs.forEach((e, k) => write(k ? '②' : '①', rightHTML(s, e)));
                return { ok: true, right: flds.map((f) => f.key), why: 'Yes. ' + s.eqs.map((e) => e.because).join(' '), next };
              }
              misses++;
              if (!unread.length) tries++;
              const wrong = flds.filter((f, i) => matched[i] < 0).map((f) => f.key);
              // name the mistake if her line is one of the known traps
              let why = 'One of those does not match the story. Read it again, one sentence at a time.';
              for (const p of parsed.filter(Boolean)) for (const e of s.eqs) for (const o of e.options) {
                if (!o.ok && L.equivalent(p, o.eq)) { why = o.why; note('trap', { trap: o.trap }); }
              }
              if (tries >= 3) {
                s.eqs.forEach((e, k) => write(k ? '②' : '①', rightHTML(s, e)));
                return { ok: false, lock: true, why: 'Here they are — compare them with yours. ' + s.eqs.map((e) => e.because).join(' '), wrong, next };
              }
              return { ok: false, why, wrong };
            },
          });
          cur.fill = () => {
            const ins = Object.values(cur.inputs);
            s.eqs.forEach((e, k) => { ins[k].value = L.dispText(e.options.find((o) => o.ok).disp || layoutOf(s, e)(e.eq)); });
          };
        }

        /* --- solve: values for the letters, with sense checks built into the box --- */
        function solveStep() {
          promptEl.innerHTML = (s.solvePrompt || 'Now solve the pair.') + ' <span class="kind-blurb">Use substitution or elimination on paper, then put your answers in.</span>';
          const letters = s.letters.map((l) => l.v);
          let tries = 0;
          cur = MathLab.fields(area, {
            fields: letters.map((v) => ({ key: v, label: mathHTML(v) + ' =' })),
            onSubmit(v) {
              const empty = letters.filter((k) => !v[k]);
              if (empty.length) {
                note('unfinished', { what: 'one value' });
                return { ok: false, why: 'The question needs ' + (letters.length > 1 ? 'every' : 'the') + ' value — ' + empty.join(' and ') + ' too.', wrong: empty };
              }
              const vals = {};
              for (const k of letters) { vals[k] = L.parseNumber(v[k]); if (!vals[k]) return { ok: false, why: 'Write a number for ' + k + '.', wrong: [k] }; }

              // sense first: a story has rules that algebra alone doesn't know
              const silly = letters.filter((k) => (s.whole || []).includes(k) && (!L.isInt(vals[k]) || L.sign(vals[k]) < 0)
                || (s.positive || []).includes(k) && L.sign(vals[k]) <= 0
                || (s.between && (L.num(vals[k]) < s.between.lo || L.num(vals[k]) > s.between.hi)));
              if (silly.length && tries < 2) {
                misses++; tries++;
                note('trap', { trap: 'nonsense-answer' });
                const k = silly[0];
                const what = (s.letters.find((l) => l.v === k) || {}).means || k;
                return { ok: false, why: k + ' = ' + qNice(vals[k]) + ' can\'t be right: ' + what + ' can\'t be ' + qNice(vals[k]) + '. Check your equations against the story.', wrong: silly };
              }

              const okAll = letters.every((k) => L.eq(vals[k], s.sol[k]));
              if (okAll) {
                write('', letters.map((k) => mathHTML(k) + ' = ' + valFmt(s, k)(s.sol[k])).join(', '));
                return { ok: true, right: letters, next,
                  why: 'They work in ' + (s.eqs.length > 1 ? 'both equations' : 'the equation') + ':<div class="checks">' + checksFor(s) + '</div>' };
              }
              misses++; tries++;
              const checks = s.eqs.map((e, i) => L.checkHTML(e.eq, vals, s.order, i ? '②' : '①')).join('');
              if (tries >= 3) {
                write('', letters.map((k) => mathHTML(k) + ' = ' + valFmt(s, k)(s.sol[k])).join(', '));
                return { ok: false, lock: true, next, wrong: letters,
                  why: 'The solution is ' + letters.map((k) => k + ' = ' + qNice(s.sol[k])).join(', ') + '. It works:<div class="checks">' + checksFor(s) + '</div>' + solveTip(s) };
              }
              return { ok: false, why: 'Put them back in: <div class="checks">' + checks + '</div>', wrong: letters.filter((k) => !L.eq(vals[k], s.sol[k])) };
            },
          });
          cur.fill = () => letters.forEach((k) => { cur.inputs[k].value = L.qText(s.sol[k]); });
        }

        /* --- from the letter to every quantity the question asked about --- */
        function derivedStep() {
          promptEl.innerHTML = 'The question asked for all of them. Fill in each one.';
          const keys = s.derived.map((d, i) => 'd' + i);
          let tries = 0;
          cur = MathLab.fields(area, {
            fields: s.derived.map((d, i) => ({ key: keys[i], label: d.label, long: true })),
            onSubmit(v) {
              const empty = keys.filter((k) => !v[k]);
              if (empty.length) { note('unfinished', { what: 'stopped at the letter' }); return { ok: false, why: 'You found ' + s.letters[0].v + ' — now answer what was asked: every one.', wrong: empty }; }
              const want = s.derived.map((d) => d.value(s.sol));
              const wrong = keys.filter((k, i) => { const g = L.parseNumber(v[k]); return !g || !L.eq(g, want[i]); });
              if (!wrong.length) {
                write('', s.derived.map((d, i) => d.label + ': ' + qNice(want[i])).join(', '));
                return { ok: true, right: keys, next, why: 'Each one from its expression: ' + s.derived.map((d, i) => d.label + ' = ' + d.html + ' = ' + qNice(want[i])).join(', ') + '.' };
              }
              misses++; tries++;
              if (tries >= 3) {
                write('', s.derived.map((d, i) => d.label + ': ' + qNice(want[i])).join(', '));
                return { ok: false, lock: true, next, why: s.derived.map((d, i) => d.label + ' = ' + qNice(want[i])).join(', ') + '.', wrong };
              }
              return { ok: false, why: 'Use the expressions: ' + s.derived.map((d) => d.label + ' = ' + d.html).join(', ') + '.', wrong };
            },
          });
          cur.fill = () => s.derived.forEach((d, i) => { cur.inputs['d' + i].value = L.qText(d.value(s.sol)); });
        }

        /* --- the "hence" part, or the decision --- */
        function finalStep() {
          const f = s.final;
          promptEl.innerHTML = f.prompt;
          if (f.options) {
            cur = MathLab.choice(area, {
              options: f.options.map((o) => ({ html: o.label, ok: o.ok, why: o.why, trap: o.trap })),
              onMiss: () => misses++,
              onDone: () => { write('', f.options.find((o) => o.ok).label); next(); },
            });
            return;
          }
          let tries = 0;
          cur = MathLab.fields(area, {
            fields: [{ key: 'v', label: 'answer', long: true, unit: f.unit }],
            onSubmit(v) {
              if (!v.v) { note('unfinished', { what: 'hence part' }); return { ok: false, why: 'Finish the question — this part counts too.', wrong: ['v'] }; }
              const g = L.parseNumber(v.v);
              if (!g) return { ok: false, why: 'Write a number.', wrong: ['v'] };
              if (L.eq(g, f.value)) { write('', qNice(f.value) + ' ' + f.unit); return { ok: true, right: ['v'], next, why: f.because || 'Yes — from the values you found.' }; }
              misses++; tries++;
              const t = (f.traps || []).find((tr) => L.eq(tr.value, g));
              if (t) note('trap', { trap: 'hence-' + s.family });
              if (tries >= 3) { write('', qNice(f.value) + ' ' + f.unit); return { ok: false, lock: true, next, why: 'It is ' + qNice(f.value) + ' ' + f.unit + '. ' + (f.because || ''), wrong: ['v'] }; }
              return { ok: false, why: t ? t.why : 'Use the values you found.', wrong: ['v'] };
            },
          });
          cur.fill = () => { cur.inputs.v.value = L.qText(f.value); };
        }

        function settle() {
          stuckBtn.hidden = true;
          promptEl.innerHTML = '';
          if (opts.kindOnly) {
            const box = document.createElement('div');
            box.className = 'bridge';
            box.innerHTML = '<b>The equations</b><div class="written">' + s.eqs.map((e) => rightHTML(s, e)).join('<br>') + '</div>';
            stage.appendChild(box);
          } else {
            const box = document.createElement('div');
            box.className = 'bridge';
            box.innerHTML = '<b>Answer</b><div class="written">' + s.sentence + '</div>' +
              '<div class="checks">' + s.eqs.map((e, i) => (e.layout || s.layout
                ? L.checkDispHTML(layoutOf(s, e)(e.eq), s.sol, i ? '②' : '①', s.cents2 ? L.qMoney : qNice)
                : L.checkHTML(e.eq, s.sol, s.order, i ? '②' : '①', s.cents2 ? L.qMoney : qNice))).join('') + '</div>' +
              '<p class="process">' + (misses === 0 && stuck === 0 ? 'Every step yours ⭐️' : 'Finished it') + '</p>';
            stage.appendChild(box);
            if (s.graph) costGraph(stage, s);
          }
          round.firstTry = misses === 0 && stuck === 0;
          submit(true, Math.max(4, 20 - 3 * misses - 3 * stuck));
          const nb = document.querySelector('[data-next]');
          if (nb) nb.scrollIntoView({ block: 'center', behavior: 'smooth' });
        }

        next();
      },
    };
    return round;
  }

  /* ---------- match the story: equations -> which story? ---------- */
  function matchRound() {
    const fams = shuffle(Object.keys(Stories.FAMILY)).slice(0, 3);
    const stories = fams.map((f) => Stories.make(f));
    const target = stories[0];
    return {
      prompt: 'Which story do these equations describe?',
      question: '',
      solution: 'the ' + Stories.KINDS[target.family].label.toLowerCase() + ' story',
      mount(stage, submit) {
        const eqs = document.createElement('div');
        eqs.className = 'eqs';
        eqs.innerHTML = target.eqs.map((e, i) => '<div class="eqn ' + (i ? 'b' : 'a') + '"><span class="tag">' + (i ? '②' : '①') + '</span>' + rightHTML(target, e) + '</div>').join('') +
          '<div class="letters">' + target.letters.map((l) => '<span>' + mathHTML(l.v) + ' = ' + l.means + '</span>').join('') + '</div>';
        stage.appendChild(eqs);
        MathLab.choice(stage, {
          options: shuffle(stories.map((st) => ({
            html: '<span style="font-size:.9rem;font-weight:600">' + st.text + '</span>',
            ok: st === target,
            trap: 'match-story',
            why: st === target ? '' : 'Check the numbers: do they appear in this story, doing the same job?',
          }))),
          onDone(misses) { submit(misses === 0, undefined, target.sentence); },
        });
      },
    };
  }

  return [
    { name: '📖 Worked example', make: workedRound },
    { name: 'Mixed', make: () => makeRound({ kind: true }) },
    { name: 'Which kind?', make: () => makeRound({ kind: true, kindOnly: true }) },
    { name: 'Count & value', make: () => makeRound({ family: ['count-value', 'relation'] }) },
    { name: 'Shopping lists', make: () => makeRound({ family: 'two-baskets' }) },
    { name: 'Which deal?', make: () => makeRound({ family: 'break-even' }) },
    { name: 'Shapes', make: () => makeRound({ family: 'shape' }) },
    { name: 'Ages & numbers', make: () => makeRound({ family: ['age', 'number'] }) },
    { name: 'Mixtures & fractions', make: () => makeRound({ family: ['mixture', 'fraction'] }) },
    { name: '✍️ Write it yourself', make: () => makeRound({ typed: true }) },
    { name: 'Match the story', make: matchRound },
  ];
  },
});

MathLab.app('step-builder', {
  emoji: '🪜',
  ownHints: true,          // this app has its own three-rung ladder
  title: 'Step Builder',
  tagline: 'You choose the move. The working writes itself.',
  blurb: 'Pick the next move, one step at a time, and build the whole solution.',

  build() {
  const { pick, shuffle, mathHTML } = MathLab;
  const { cloneAll, MOVES, suggest, render, theFraction, predictions,
          reachedGoal, PALETTE, DONE_LABEL, notYet, bannedValues } = Algebra;

  function makeRound(pool, opts = {}) {
    const problem = pick(pool)();
    const mixed = !!opts.mixed;

    // The banned values come from the bottom of the ORIGINAL fraction. That is the whole
    // point of them: they survive cancelling, and they are the marks people throw away.
    const banned = bannedValues(problem.items);
    const asksBanned = !!(banned && banned.values && banned.values.length);

    const round = {
      prompt: problem.goal === 'factor' ? 'Write this as a product.'
            : problem.goal === 'fraction' ? 'Cancel this down as far as it goes.'
            : 'What is the next move?',
      question: '',
      hint: 'Read the whole line before you touch anything.',
      solution: '',

      mount(stage, submit) {
        let items = cloneAll(problem.items);
        const lines = [render(items)];
        const whys = ['Start.'];   // the reason for each line, for the "How it works" panel
        let wrongMoves = 0;
        let hintRung = 0;
        let finished = false;
        let bannedMissed = false;
        let badPredictions = 0;

        stage.innerHTML = `
          <p class="chip-label" data-type></p>
          <ol class="working" data-working></ol>
          <p class="why-line" data-why> </p>
          <div class="moves" data-moves></div>
          <div class="answer-row">
            <button type="button" class="ghost" data-stuck>Stuck?</button>
          </div>
        `;

        const el = {
          type: stage.querySelector('[data-type]'),
          working: stage.querySelector('[data-working]'),
          why: stage.querySelector('[data-why]'),
          moves: stage.querySelector('[data-moves]'),
          stuck: stage.querySelector('[data-stuck]'),
        };

        // In Mixed the label would name the move, which is exactly the decision she is
        // supposed to be making. Deciding is the skill interleaving trains.
        if (mixed) el.type.remove(); else el.type.textContent = problem.type;

        const say = (text, tone) => {
          el.why.className = 'why-line' + (tone ? ' ' + tone : '');
          el.why.innerHTML = text;
        };

        function paint() {
          el.working.innerHTML = lines
            .map((line, i) =>
              '<li' + (i === lines.length - 1 ? ' class="now"' : '') + '>' + mathHTML(line) + '</li>')
            .join('');

          el.moves.innerHTML = '';
          for (const key of PALETTE[problem.goal]) {
            const b = document.createElement('button');
            b.type = 'button';
            b.className = 'move';
            b.textContent = MOVES[key].label;
            b.disabled = finished;
            b.addEventListener('click', () => choose(key));
            el.moves.appendChild(b);
          }

          const done = document.createElement('button');
          done.type = 'button';
          done.className = 'move done';
          done.textContent = DONE_LABEL[problem.goal];
          done.disabled = finished;
          done.addEventListener('click', claimDone);
          el.moves.appendChild(done);
        }

        function choose(key) {
          if (finished) return;
          const move = MOVES[key];

          if (!move.can(items)) {
            wrongMoves += 1;
            say(move.refuse(items), 'bad');   // the line is left exactly as it was
            return;
          }

          const guess = predictions(key, items);
          if (guess) { predict(key, guess); return; }
          applyMove(key);
        }

        function applyMove(key) {
          const { next, why } = MOVES[key].apply(items);
          items = next;
          lines.push(render(items));
          whys.push(why);
          paint();

          if (reachedGoal(problem.goal, items)) {
            say(why + ' <b>That is as far as it goes — now say so.</b>', 'good');
            el.moves.querySelector('.done').focus();
          } else {
            say(why, 'good');
          }
        }

        /* Right move chosen — now what does it actually give? The wrong options are the
           real mistakes, so she has to look at x² + 25 and turn it down. */
        function predict(key, guess) {
          el.moves.querySelectorAll('button').forEach((b) => { b.disabled = true; });

          const box = document.createElement('div');
          box.className = 'predict';
          box.innerHTML = '<b>' + MOVES[key].label + ' — so what does that give?</b>' +
                          '<div class="options" data-guess></div>';
          const holder = box.querySelector('[data-guess]');

          for (const opt of shuffle(guess.options.slice())) {
            const b = document.createElement('button');
            b.type = 'button';
            b.className = 'option';
            b.innerHTML = mathHTML(opt.text);
            b.addEventListener('click', () => {
              if (opt.ok) {
                b.classList.add('hit');
                box.querySelectorAll('button').forEach((x) => { x.disabled = true; });
                setTimeout(() => { box.remove(); applyMove(key); }, 420);
              } else {
                badPredictions += 1;
                b.classList.add('miss');
                b.disabled = true;
                say(opt.why, 'bad');
              }
            });
            holder.appendChild(b);
          }

          el.moves.insertAdjacentElement('beforebegin', box);
          say('Pick the line it turns into.');
        }

        function claimDone() {
          if (finished) return;

          if (!reachedGoal(problem.goal, items)) {
            wrongMoves += 1;
            say(notYet(problem.goal, items), 'bad');
            return;
          }

          finished = true;
          round.solution = render(items);
          round.explain = '<ol>' + lines.map((ln, i) => '<li><span class="m">' + mathHTML(ln) + '</span>' + (whys[i] ? '<br>' + whys[i] : '') + '</li>').join('') + '</ol>';
          paint();
          el.stuck.disabled = true;

          if (asksBanned) askBanned();
          else settle();
        }

        /* The second half of a fraction question. Cancelling makes a value LOOK harmless —
           (x + 7) disappears and x = -7 stops being visible — so it is asked separately,
           and the wrong answer on offer is exactly the one that forgets it. */
        function askBanned() {
          const L = banned.letter;
          const decoys = new Set(banned.values);
          for (const v of banned.values) decoys.add(-v);
          decoys.add(0);
          const options = [...decoys].sort((a, b) => a - b).slice(0, 6);
          const chosen = new Set();

          const box = document.createElement('div');
          box.className = 'banned';
          box.innerHTML =
            '<b>One more thing</b>' +
            '<p>Which values may <i class="var">' + L + '</i> never take? ' +
            'Take them from the bottom you <em>started</em> with.</p>' +
            '<div class="chips" data-banned></div>' +
            '<div class="answer-row"><button type="button" data-banned-check>Check</button></div>' +
            '<p class="why-line" data-banned-why> </p>';
          stage.appendChild(box);

          const row = box.querySelector('[data-banned]');
          const buttons = options.map((v) => {
            const b = document.createElement('button');
            b.type = 'button';
            b.className = 'chip';
            b.setAttribute('aria-pressed', 'false');
            b.innerHTML = mathHTML(L) + ' = ' + v;
            b.addEventListener('click', () => {
              if (chosen.has(v)) chosen.delete(v); else chosen.add(v);
              b.setAttribute('aria-pressed', String(chosen.has(v)));
            });
            row.appendChild(b);
            return b;
          });

          const why = box.querySelector('[data-banned-why]');
          const check = box.querySelector('[data-banned-check]');

          check.addEventListener('click', () => {
            const want = new Set(banned.values);
            const right = chosen.size === want.size && [...chosen].every((v) => want.has(v));

            buttons.forEach((b, i) => {
              b.disabled = true;
              if (want.has(options[i])) b.classList.add('hit');
              else if (chosen.has(options[i])) b.classList.add('miss');
            });
            check.disabled = true;

            if (!right) {
              bannedMissed = true;
              const missed = banned.values.filter((v) => !chosen.has(v));
              why.className = 'why-line bad';
              why.innerHTML = missed.length
                ? 'Missed ' + missed.map((v) => L + ' = ' + v).join(' and ') +
                  '. A value that cancelled away still breaks the fraction you started with.'
                : 'Those extra ones are fine — only the bottom you started with can ban a value.';
            } else {
              why.className = 'why-line good';
              why.innerHTML = 'Yes. Write them next to the answer — they are free marks.';
            }
            settle();
          });
        }

        function settle() {
          const steps = lines.length - 1;
          const clean = wrongMoves === 0 && hintRung < 3 && !bannedMissed && badPredictions === 0;

          const answer = lines.join('  =  ') +
            (asksBanned ? ',   ' + banned.values.map((v) => banned.letter + ' ≠ ' + v).join(', ') : '');

          const bridge = document.createElement('div');
          bridge.className = 'bridge';
          bridge.innerHTML =
            '<b>Your working</b>' +
            '<div class="written">' + mathHTML(answer) + '</div>' +
            '<p class="process">' + steps + ' step' + (steps === 1 ? '' : 's') +
            (clean ? ' · found every move yourself ⭐️' : ' · finished it') + '</p>';
          stage.appendChild(bridge);

          // Finishing is always the win — that is deliberate, and it is why `correct` is
          // true whatever happened. What varies is the points, which score the process:
          // wrong turns, hints and wrong predictions each cost, with a floor so a messy
          // round still pays something.
          const points = Math.max(4, 20 - 3 * wrongMoves - 2 * hintRung - 3 * badPredictions - (bannedMissed ? 3 : 0));
          submit(true, points);

          // The next-question button sits below the card, which on a phone is off-screen —
          // and an off-screen button reads as a dead end. Bring it into view.
          const next = document.querySelector('[data-next]');
          if (next) next.scrollIntoView({ block: 'center', behavior: 'smooth' });
        }

        // Three rungs, and only the last one names the move.
        function stuck() {
          if (finished) return;
          hintRung = Math.min(hintRung + 1, 3);

          if (hintRung === 1) {
            const has = (k) => items.some((i) => i.k === k);
            say(theFraction(items) || items.filter((i) => i.k === 'f').length
              ? 'It is a fraction. That changes everything — do <b>not</b> open brackets here.'
              : has('x') ? 'Two fractions, side by side. Get them into one first.'
              : has('b') || has('p') ? 'Look at the whole line first. A bracket always goes before anything else.'
              : has('m') || has('d') || has('e') ? 'Something is being multiplied, divided or raised to a power. There is a rule for that.'
              : problem.goal === 'factor' ? 'You are going the other way this time — towards brackets, not away from them.'
              : 'No brackets here. So it is about shapes: which ones match?');
            return;
          }

          if (hintRung === 2) {
            const f = theFraction(items);
            say(f ? 'Can the top or the bottom be written as a product? That is what you cancel with.'
                  : items.some((i) => i.k === 'b' || i.k === 'p') ? 'There is still a bracket on that line.'
                  : items.some((i) => i.k === 'm') ? 'Two powers of the same letter are being multiplied.'
                  : problem.goal === 'factor' ? 'What do all the terms have in common?'
                  : 'No brackets left. So look at the shapes — are any two the same?');
            return;
          }

          const key = suggest(problem.goal, items);
          say(key
            ? 'The move is: <b>' + MOVES[key].label + '</b>.'
            : 'Nothing left to do — press <b>' + DONE_LABEL[problem.goal] + '</b>.');
        }

        el.stuck.addEventListener('click', stuck);
        paint();
        say('Read the line, then pick a move.');
      },
    };

    return round;
  }

  return [
    { name: 'Mixed', make: () => makeRound(Problems.EVERYTHING, { mixed: true }) },
    { name: 'Brackets', make: () => makeRound(Problems.BRACKETS) },
    { name: 'Powers', make: () => makeRound(Problems.POWERS) },
    { name: 'Collecting', make: () => makeRound(Problems.COLLECT) },
    { name: 'Factorising', make: () => makeRound(Problems.FACTOR) },
    { name: 'Fractions', make: () => makeRound(Problems.FRACTIONS) },
    { name: 'Fraction sums', make: () => makeRound(Problems.FRACTION_SUMS) },
  ];
  },
});

MathLab.app('like-terms', {
  emoji: '🧲',
  title: 'Like Terms Hunt',
  tagline: 'A block is a thing. Plus and minus are the joints between them.',
  blurb: 'Join the blocks that match. Watch the ones that do not.',

  build() {
  const { rnd, rndNonZero, pick, sample, shuffle, formatTerm, formatSum, signature, mathHTML } = MathLab;

  const FAMILIES = [['x', 'y'], ['p', 'q'], ['a', 'b'], ['m', 'n']];

  /** All the variable shapes a term can take for one letter pair. */
  const shapesFor = ([u, v]) => [
    {},
    { [u]: 1 }, { [v]: 1 },
    { [u]: 2 }, { [v]: 2 },
    { [u]: 1, [v]: 1 },
    { [u]: 2, [v]: 1 }, { [u]: 1, [v]: 2 },
    { [u]: 3 },
  ];

  const term = (vars) => ({ coeff: rndNonZero(-6, 8), vars });

  /** Name a shape the way the wall chart names it: squares, bars, numbers. */
  function shapeName(vars, plural = true) {
    const keys = Object.keys(vars);
    if (keys.length === 0) return plural ? 'numbers' : 'number';
    if (keys.length === 1 && vars[keys[0]] === 1) return plural ? 'bars' : 'bar';
    if (keys.length === 1 && vars[keys[0]] === 2) return plural ? 'squares' : 'square';
    if (keys.length === 1 && vars[keys[0]] === 3) return plural ? 'cubes' : 'cube';
    return formatTerm({ coeff: 1, vars }) + (plural ? ' blocks' : ' block');
  }

  /* ---- Level 1: tap every term like the glowing one ---- */

  function spotRound() {
    const shapes = shuffle(shapesFor(pick(FAMILIES)));
    const targetShape = shapes[0];
    const likeCount = rnd(1, 3);
    const decoyShapes = sample(shapes.slice(1), rnd(3, 4));

    const target = term(targetShape);
    const likes = Array.from({ length: likeCount }, () => term(targetShape));
    const decoys = decoyShapes.map(term);

    const others = shuffle([...likes, ...decoys]);
    const wanted = new Set(others.map((t, i) => (signature(t) === signature(target) ? i : -1))
                                 .filter((i) => i >= 0));

    return {
      prompt: 'Tap every block that is the <b>same shape</b> as the glowing one, then press Check.',
      question: '',
      hint: 'Same letters <i>and</i> same powers. The number in front does not matter — ' +
            '3<i class="var">pq</i> and −7<i class="var">pq</i> are the same shape.',
      solution: likes.map((t) => formatTerm(t)).join(', '),
      rightWhy: 'Same letters with the same powers — the number in front never matters.',
      explain: '<ol><li>The shape of ' + mathHTML(formatTerm(target)) + ' is its letters and their powers: ' + mathHTML(formatTerm({ coeff: 1, vars: target.vars })) + '.</li>' +
        '<li>A term is the same shape only if it has exactly those letters, each to exactly that power. Order does not matter (pq = qp).</li>' +
        '<li>Same shape here: ' + likes.map((t) => mathHTML(formatTerm(t))).join(', ') + '. The others differ in a letter or a power.</li></ol>',

      mount(stage, submit) {
        const chosen = new Set();

        const targetRow = document.createElement('div');
        targetRow.className = 'chips';
        targetRow.style.marginBottom = '18px';
        const targetChip = document.createElement('span');
        targetChip.className = 'chip target';
        targetChip.innerHTML = mathHTML(formatTerm(target));
        targetRow.appendChild(targetChip);

        const row = document.createElement('div');
        row.className = 'chips';

        const buttons = others.map((t, i) => {
          const b = document.createElement('button');
          b.type = 'button';
          b.className = 'chip';
          b.setAttribute('aria-pressed', 'false');
          b.innerHTML = mathHTML(formatTerm(t));
          b.addEventListener('click', () => {
            if (chosen.has(i)) chosen.delete(i); else chosen.add(i);
            b.setAttribute('aria-pressed', String(chosen.has(i)));
          });
          row.appendChild(b);
          return b;
        });

        const actions = document.createElement('div');
        actions.className = 'answer-row';
        const check = document.createElement('button');
        check.type = 'button';
        check.textContent = 'Check';
        actions.appendChild(check);

        check.addEventListener('click', () => {
          const correct = chosen.size === wanted.size && [...chosen].every((i) => wanted.has(i));
          buttons.forEach((b, i) => {
            b.disabled = true;
            if (wanted.has(i)) b.classList.add('hit');
            else if (chosen.has(i)) b.classList.add('miss');
          });
          check.disabled = true;
          submit(correct);
        });

        stage.append(targetRow, row, actions);
      },
    };
  }

  /* ---- Level 2: join the blocks ----
     The mechanic carries the idea the wall chart can only assert. Two blocks of the same
     shape fuse and the shape visibly does not change, which is the whole of 3x²+4x²=7x².
     Two blocks of different shapes refuse to fuse and the joint between them lights up,
     so "you can't do that" is something the student watches instead of something they
     are told. Every round ends on the written line, or none of this transfers to paper. */

  // Variation theory: hold the shapes still for three rounds and change only the numbers,
  // so what varies is what the student is meant to notice.
  let seq = null;

  function nextSpec() {
    if (seq && seq.left > 0) {
      seq.left -= 1;
      return seq;
    }
    const family = pick(FAMILIES);
    const shapes = shuffle(shapesFor(family)).slice(0, rnd(2, 3));
    seq = { family, shapes, left: 2 };
    return seq;
  }

  function joinRound() {
    const { shapes } = nextSpec();

    const terms = [];
    for (const vars of shapes) {
      for (let i = 0, n = rnd(2, 3); i < n; i++) terms.push(term(vars));
    }
    shuffle(terms);

    const original = formatSum(terms);

    const round = {
      prompt: 'Tap two blocks to join them. Only blocks of the <b>same shape</b> can join.',
      question: '',
      hint: 'The + and − between blocks are joints, not instructions. ' +
            'Joining adds the numbers in front — it never changes the shape.',
      solution: '',   // filled in once the round resolves

      mount(stage, submit) {
        const live = terms.map((t) => ({ ...t }));
        let picked = null;
        let mistakes = 0;

        const why = document.createElement('p');
        why.className = 'why-line';
        why.textContent = ' ';

        const expr = document.createElement('div');
        expr.className = 'expr';

        stage.append(why, expr);

        const say = (text, tone) => {
          why.className = 'why-line' + (tone ? ' ' + tone : '');
          why.innerHTML = text;
        };

        function finish() {
          const answer = live.length ? formatSum(live) : '0';
          round.solution = answer;

          const bridge = document.createElement('div');
          bridge.className = 'bridge';
          bridge.innerHTML =
            '<b>The same move, written down</b>' +
            '<div class="written">' + mathHTML(original) + ' = ' + mathHTML(answer) + '</div>';
          stage.appendChild(bridge);

          submit(mistakes === 0);
        }

        function render(flash) {
          expr.innerHTML = '';

          live.forEach((t, i) => {
            if (i > 0) {
              const j = document.createElement('span');
              j.className = 'joint';
              j.textContent = t.coeff < 0 ? '−' : '+';
              if (flash && flash.joints.includes(i)) j.classList.add('blocked');
              expr.appendChild(j);
            }

            const b = document.createElement('button');
            b.type = 'button';
            b.className = 'chip';
            if (picked === i) b.classList.add('picked');
            if (flash && flash.shake.includes(i)) b.classList.add('shake');
            if (flash && flash.fuse === i) b.classList.add('fused');

            // after the first block the sign lives in the joint, so show the size only
            const shown = i === 0 ? formatTerm(t) : formatTerm({ ...t, coeff: Math.abs(t.coeff) });
            b.innerHTML = mathHTML(shown);
            b.addEventListener('click', () => tap(i));
            expr.appendChild(b);
          });
        }

        function tap(i) {
          if (picked === null) {
            picked = i;
            say('Now tap the block you want to join it to.');
            render();
            return;
          }
          if (picked === i) {
            picked = null;
            say(' ');
            render();
            return;
          }

          const a = live[picked];
          const b = live[i];

          if (signature(a) !== signature(b)) {
            mistakes += 1;
            const between = [];
            for (let k = Math.min(picked, i) + 1; k <= Math.max(picked, i); k++) between.push(k);
            say(
              formatTerm(a) + ' is ' + shapeName(a.vars) + ', ' +
              formatTerm(b) + ' is ' + shapeName(b.vars) +
              ' — different shapes never join. The joint holds.',
              'bad',
            );
            render({ shake: [picked, i], joints: between, fuse: null });
            picked = null;
            return;
          }

          const sum = a.coeff + b.coeff;
          const name = shapeName(a.vars);
          const keep = Math.min(picked, i);
          const drop = Math.max(picked, i);

          if (sum === 0) {
            live.splice(drop, 1);
            live.splice(keep, 1);
            say(a.coeff + ' and ' + b.coeff + ' cancel — no ' + name + ' left.', 'good');
            picked = null;
            render();
          } else {
            live[keep] = { coeff: sum, vars: a.vars };
            live.splice(drop, 1);
            say(
              a.coeff + ' and ' + b.coeff + ' make ' + sum + ' ' + name +
              '. The shape did not change.',
              'good',
            );
            picked = null;
            render({ shake: [], joints: [], fuse: keep });
          }

          const done = !live.some((t, x) => live.some((u, y) => x !== y && signature(t) === signature(u)));
          if (done) finish();
        }

        render();
      },
    };

    return round;
  }

  /* ---- Levels 3 & 4: write the collected expression down ----
     This is the transfer step. Blocks are the model; standard notation is the exam. */

  function collectRound({ groups, perGroup }) {
    const shapes = shuffle(shapesFor(pick(FAMILIES))).slice(0, groups);

    const terms = [];
    const totals = [];

    for (const vars of shapes) {
      const count = rnd(perGroup[0], perGroup[1]);
      let sum = 0;
      for (let i = 0; i < count; i++) {
        const t = term(vars);
        terms.push(t);
        sum += t.coeff;
      }
      if (sum !== 0) totals.push({ coeff: sum, vars });
    }

    if (!totals.length) return collectRound({ groups, perGroup });   // everything cancelled — redraw

    const shown = shuffle(terms);
    const answer = formatSum(totals);

    return {
      prompt: 'Collect the like terms and write the answer:',
      question: mathHTML(formatSum(shown)),
      hint: 'Join the matching shapes first, then add the numbers in front. ' +
            'The letters and powers stay exactly as they are.',
      solution: answer,
      explain: '<ol>' + totals.map((t) => {
        const same = terms.filter((x) => signature(x) === signature(t));
        return '<li>' + same.map((x) => mathHTML(formatTerm(x))).join(', ') + ' are the same shape: add the numbers in front, ' +
          same.map((x) => x.coeff).join(' + ').replace(/\+ -/g, '− ') + ' = ' + t.coeff + ' → ' + mathHTML(formatTerm(t)) + '</li>';
      }).join('') + '<li>Different shapes stay separate: <b>' + mathHTML(answer) + '</b></li></ol>',

      mount(stage, submit) {
        MathLab.textAnswer(stage, submit, {
          placeholder: 'e.g. 6pq',
          check: (raw) => MathLab.sameExpression(raw, answer),
        });
      },
    };
  }

  // Joining is the game. It lands first because it is what carries the idea; spotting is
  // the easier warm-up you drop back to, not the front door.
  return [
    { name: 'Join blocks', make: joinRound },
    { name: 'Spot the shape', make: spotRound },
    { name: 'Write it down', make: () => collectRound({ groups: 1, perGroup: [3, 3] }) },
    { name: 'Two shapes', make: () => collectRound({ groups: 2, perGroup: [2, 3] }) },
  ];
  },
});

MathLab.app('substitution', {
  emoji: '🔢',
  title: 'Substitution Machine',
  tagline: 'Swap the letters for their numbers, then work it out.',
  blurb: 'Put numbers in place of letters and work out the value.',

  build() {
  const { rnd, rndNonZero, pick, mathHTML, sup } = MathLab;

  const FAMILIES = [
    ['k', 'l', 'm'],
    ['a', 'b', 'c'],
    ['p', 'q', 'r'],
    ['d', 'e', 'f'],
  ];

  /** "k = 3" chips for the given-values strip. */
  const givens = (names, vals) => names.map((n) => n + ' = ' + vals[n]);

  /** Accepts 7, -7, 3.5 or 7/2. */
  function numericCheck(want) {
    return (raw) => {
      const s = raw.replace(/\s+/g, '').replace(/[−–—]/g, '-');
      let val;
      if (/^-?\d+\/-?\d+$/.test(s)) {
        const [a, b] = s.split('/').map(Number);
        if (b === 0) return false;
        val = a / b;
      } else if (/^-?\d*\.?\d+$/.test(s)) {
        val = Number(s);
      } else {
        return false;
      }
      return Math.abs(val - want) < 1e-9;
    };
  }

  const round = (parts) => ({
    ...parts,
    mount(stage, submit) {
      MathLab.textAnswer(stage, submit, { check: numericCheck(parts.value), placeholder: 'number' });
    },
  });

  /* ---- Level 1: pure products, e.g. klm or 3ab ---- */

  function productRound() {
    const [x, y, z] = pick(FAMILIES);
    const vals = { [x]: rndNonZero(-6, 8), [y]: rndNonZero(-6, 8), [z]: rndNonZero(-6, 8) };
    const useThird = Math.random() < 0.5;
    const coeff = pick([1, 1, 2, 3, 4]);

    const names = useThird ? [x, y, z] : [x, y];
    const shown = coeff === 1 ? names.join('') : coeff + names.join('');
    const value = names.reduce((acc, n) => acc * vals[n], coeff);

    const subbed = (coeff === 1 ? '' : coeff + ' × ') + names.map((n) => (vals[n] < 0 ? '(' + vals[n] + ')' : vals[n])).join(' × ');
    return round({
      prompt: 'Find the value of:',
      question: mathHTML(shown),
      given: givens(useThird ? [x, y, z] : [x, y], vals),
      value,
      solution: String(value),
      rightWhy: subbed + ' = ' + value + '.',
      explain: '<ol><li>Letters written side by side are multiplied: ' + mathHTML(shown) + ' means ' + (coeff === 1 ? '' : coeff + ' × ') + names.join(' × ') + '.</li>' +
        '<li>Swap in the numbers, keeping negatives in brackets: ' + subbed + '.</li>' +
        '<li>Multiply. Count the negatives: an even number of them makes the answer positive, an odd number negative. = <b>' + value + '</b>.</li></ol>',
      hint: 'Replace each letter with its number, then multiply. Two negatives multiply to a positive.',
    });
  }

  /* ---- Level 2: sums and differences, e.g. 8km − 2l ---- */

  function mixedRound() {
    const [x, y, z] = pick(FAMILIES);
    const vals = { [x]: rndNonZero(-5, 7), [y]: rndNonZero(-5, 7), [z]: rndNonZero(-5, 7) };

    const c1 = rnd(2, 9);
    const c2 = rnd(2, 9);
    const minus = Math.random() < 0.6;

    const first = c1 * vals[x] * vals[y];
    const second = c2 * vals[z];
    const value = minus ? first - second : first + second;

    const question = mathHTML(c1 + x + y) + (minus ? ' − ' : ' + ') + mathHTML(c2 + z);

    const b = (v) => (v < 0 ? '(' + v + ')' : v);
    return round({
      prompt: 'Find the value of:',
      question,
      given: givens([x, y, z], vals),
      value,
      solution: String(value),
      rightWhy: first + (minus ? ' − ' : ' + ') + b(second) + ' = ' + value + '.',
      explain: '<ol><li>First part: ' + c1 + ' × ' + b(vals[x]) + ' × ' + b(vals[y]) + ' = ' + first + '.</li>' +
        '<li>Second part: ' + c2 + ' × ' + b(vals[z]) + ' = ' + second + '.</li>' +
        '<li>Then ' + first + (minus ? ' − ' : ' + ') + b(second) + ' = <b>' + value + '</b>' + (minus && second < 0 ? ' (taking away a negative adds)' : '') + '.</li></ol>',
      hint: 'Do each part on its own first, then subtract or add. ' +
            c1 + '<i class="var">' + x + '</i><i class="var">' + y + '</i> means ' +
            c1 + ' × ' + vals[x] + ' × ' + vals[y] + '.',
    });
  }

  /* ---- Level 3: fractions, built so the answer stays a whole number ---- */

  const frac = (num, den) =>
    '<span class="frac"><span class="num">' + num + '</span><span class="den">' + den + '</span></span>';

  /** (p + q + r) ÷ (p − r), with q chosen so it divides exactly. */
  function sumOverDifference() {
    const [x, y, z] = pick(FAMILIES);
    let vx, vz, den, k, vy;
    do {
      vx = rndNonZero(-6, 8);
      vz = rndNonZero(-6, 8);
      den = vx - vz;
      k = rndNonZero(-4, 4);
      vy = k * den - vx - vz;
    } while (den === 0 || vy === 0 || Math.abs(vy) > 40);

    const vals = { [x]: vx, [y]: vy, [z]: vz };

    return round({
      prompt: 'Find the value of:',
      question: frac(mathHTML(x + ' + ' + y + ' + ' + z), mathHTML(x + ' − ' + z)),
      given: givens([x, y, z], vals),
      value: k,
      solution: String(k),
      explain: '<ol><li>Top: ' + vx + ' + ' + vy + ' + ' + vz + ' = ' + (vx + vy + vz) + '.</li><li>Bottom: ' + vx + ' − ' + (vz < 0 ? '(' + vz + ')' : vz) + ' = ' + den + '.</li><li>Divide: ' + (vx + vy + vz) + ' ÷ ' + den + ' = <b>' + k + '</b>.</li></ol>',
      hint: 'Work out the top and the bottom separately, then divide. Top = ' +
            vx + ' + ' + vy + ' + ' + vz + '.',
    });
  }

  /** c·q ÷ (p + r), with q a multiple of (p + r). */
  function multipleOverSum() {
    const [x, y, z] = pick(FAMILIES);
    let s, vx, vz, k, vy;
    do {
      s = rndNonZero(-7, 7);
      vx = rndNonZero(-6, 8);
      vz = s - vx;
      k = rndNonZero(-3, 3);
      vy = k * s;
    } while (vz === 0 || Math.abs(vy) > 30);

    const c = pick([2, 4, 8]);
    const vals = { [x]: vx, [y]: vy, [z]: vz };
    const value = c * k;

    return round({
      prompt: 'Find the value of:',
      question: frac(mathHTML(c + y), mathHTML(x + ' + ' + z)),
      given: givens([x, y, z], vals),
      value,
      solution: String(value),
      explain: '<ol><li>Bottom: ' + vx + ' + ' + (vz < 0 ? '(' + vz + ')' : vz) + ' = ' + s + '.</li><li>Top: ' + c + ' × ' + (vy < 0 ? '(' + vy + ')' : vy) + ' = ' + c * vy + '.</li><li>Divide: ' + c * vy + ' ÷ ' + s + ' = <b>' + value + '</b>.</li></ol>',
      hint: 'Bottom first: ' + vx + ' + ' + vz + ' = ' + s +
            '. Then divide the top by it.',
    });
  }

  return [
    { name: '① Products', make: productRound },
    { name: '② Mix it up', make: mixedRound },
    { name: '③ Fractions', make: () => (Math.random() < 0.5 ? sumOverDifference() : multipleOverSum()) },
  ];
  },
});

MathLab.app('hcf-detective', {
  emoji: '🔍',
  title: 'HCF Detective',
  tagline: 'Break both terms apart. Whatever is in both is the answer.',
  blurb: 'Find what two terms have in common — the highest common factor.',

  build() {
  const { rnd, pick, shuffle, mathHTML, sup } = MathLab;

  const LETTERS = ['x', 'y', 'z', 'p', 'q', 'r', 'a', 'b', 'c'];

  /** Prime factors of n, smallest first: 26 -> [2, 13]. */
  function primes(n) {
    const out = [];
    let v = Math.abs(n);
    for (let d = 2; d * d <= v; d++) while (v % d === 0) { out.push(d); v /= d; }
    if (v > 1) out.push(v);
    return out;
  }

  /**
   * A term written out as the things it is multiplied from: 26xy²z becomes
   * 2 · 13 · x · y · y · z. Seeing the pieces IS the method — the HCF is just the
   * pieces that appear in both lists.
   */
  function pieces(term) {
    const out = primes(term.c).map(String);
    for (const k of Object.keys(term.v).sort()) {
      for (let i = 0; i < term.v[k]; i++) out.push(k);
    }
    for (const b of term.blocks || []) out.push(b);
    return out;
  }

  /** How a term is written normally: 26xy²z */
  function label(term) {
    const body = Object.keys(term.v).sort()
      .map((k) => k + (term.v[k] === 1 ? '' : sup(term.v[k]))).join('');
    const blocks = (term.blocks || []).join('');
    const c = term.c === 1 && (body || blocks) ? '' : String(term.c);
    return c + body + blocks;
  }

  /** The pieces present in both lists, counting repeats — this is the HCF. */
  function shared(a, b) {
    const pool = [...b];
    const out = [];
    for (const piece of a) {
      const at = pool.indexOf(piece);
      if (at !== -1) { out.push(piece); pool.splice(at, 1); }
    }
    return out;
  }

  const tally = (list) => {
    const m = new Map();
    for (const x of list) m.set(x, (m.get(x) || 0) + 1);
    return m;
  };

  const sameTally = (a, b) => {
    const ta = tally(a), tb = tally(b);
    if (ta.size !== tb.size) return false;
    for (const [k, v] of ta) if (tb.get(k) !== v) return false;
    return true;
  };

  /** Write a list of pieces back as a single term: [2, x, z] -> 2xz */
  function asTerm(list) {
    if (!list.length) return '1';
    let n = 1;
    const powers = new Map();
    for (const piece of list) {
      if (/^\d+$/.test(piece)) n *= Number(piece);
      else powers.set(piece, (powers.get(piece) || 0) + 1);
    }
    // letters first, then any whole brackets — b(b + 1), never (b + 1)b
    const body = [...powers.entries()]
      .sort((x, y) => {
        const bx = x[0].startsWith('('), by = y[0].startsWith('(');
        if (bx !== by) return bx ? 1 : -1;
        return x[0] < y[0] ? -1 : 1;
      })
      .map(([k, n]) => k + (n === 1 ? '' : sup(n)))
      .join('');
    return (n === 1 && body ? '' : String(n)) + body;
  }

  /* ---- the two terms ---- */

  const randomTerm = (letters, maxPower) => ({
    c: rnd(2, 30),
    v: Object.fromEntries(letters.map((k) => [k, rnd(1, maxPower)])),
  });

  function plainPair() {
    const all = shuffle(LETTERS.slice()).slice(0, 3);
    const pickSome = () => shuffle(all.slice()).slice(0, rnd(1, 3));
    const a = randomTerm(pickSome(), 3);
    const b = randomTerm(pickSome(), 3);
    return { a, b, note: 'Take the lower power of each letter — and only what appears in both.' };
  }

  /** The worksheet's harder pair: a whole bracket counts as one piece. */
  function blockPair() {
    const x = pick(LETTERS);
    const block = '(' + x + ' + 1)';
    const a = { c: rnd(2, 6), v: { [x]: 2 }, blocks: [block] };
    const b = { c: 1, v: { [x]: 1 }, blocks: [block] };
    return { a, b, note: 'A bracket is one piece. It is either in both or it is not — you never break it open.' };
  }

  function round() {
    const { a, b, note } = Math.random() < 0.25 ? blockPair() : plainPair();
    const pa = pieces(a), pb = pieces(b);
    const want = shared(pa, pb);

    return {
      prompt: 'Tap the pieces of the <b>first</b> term that also appear in the second.',
      question: mathHTML(label(a)) + '<span class="hcf-and">and</span>' + mathHTML(label(b)),
      hint: note + ' If nothing is shared, the highest common factor is just 1.',
      solution: asTerm(want),
      rightWhy: 'Exactly the pieces in both terms, multiplied together.',
      explain: '<ol><li>Break the first term into pieces: ' + pa.map((p) => mathHTML(p)).join(' · ') + '.</li>' +
        '<li>Break the second into pieces: ' + pb.map((p) => mathHTML(p)).join(' · ') + '.</li>' +
        '<li>Keep only pieces that appear in BOTH (as many times as the fewer one has): ' + (want.length ? want.map((p) => mathHTML(p)).join(' · ') : 'none') + '.</li>' +
        '<li>Multiply them: HCF = <b>' + mathHTML(asTerm(want)) + '</b>.</li></ol>',

      mount(stage, submit) {
        const chosen = [];

        stage.innerHTML = `
          <p class="piece-label">First term, broken up — tap what is also in the second</p>
          <div class="chips" data-a></div>
          <p class="piece-label">Second term, for comparing</p>
          <div class="chips" data-b></div>
          <p class="why-line" data-why> </p>
          <div class="answer-row"><button type="button" data-check>Check</button></div>
        `;

        const rowA = stage.querySelector('[data-a]');
        const rowB = stage.querySelector('[data-b]');
        const why = stage.querySelector('[data-why]');
        const check = stage.querySelector('[data-check]');

        const buttons = pa.map((piece, i) => {
          const btn = document.createElement('button');
          btn.type = 'button';
          btn.className = 'chip';
          btn.setAttribute('aria-pressed', 'false');
          btn.innerHTML = mathHTML(piece);
          btn.addEventListener('click', () => {
            const at = chosen.indexOf(i);
            if (at === -1) chosen.push(i); else chosen.splice(at, 1);
            btn.setAttribute('aria-pressed', String(chosen.includes(i)));
          });
          rowA.appendChild(btn);
          return btn;
        });

        for (const piece of pb) {
          const s = document.createElement('span');
          s.className = 'chip quiet';
          s.innerHTML = mathHTML(piece);
          rowB.appendChild(s);
        }

        check.addEventListener('click', () => {
          const picked = chosen.map((i) => pa[i]);
          const right = sameTally(picked, want);

          buttons.forEach((btn) => { btn.disabled = true; });
          check.disabled = true;

          const answer = asTerm(want);
          why.className = 'why-line ' + (right ? 'good' : 'bad');
          why.innerHTML = right
            ? 'Multiply those together and that is the HCF: <b>' + mathHTML(answer) + '</b>.'
            : 'The pieces in both are ' +
              (want.length ? want.map((p) => mathHTML(p)).join(' · ') : 'nothing') +
              ', so the HCF is <b>' + mathHTML(answer) + '</b>.';

          const bridge = document.createElement('div');
          bridge.className = 'bridge';
          bridge.innerHTML =
            '<b>Written down</b><div class="written">HCF of ' + mathHTML(label(a)) + ' and ' +
            mathHTML(label(b)) + ' = ' + mathHTML(answer) + '</div>';
          stage.appendChild(bridge);

          submit(right);
        });
      },
    };
  }

  return [{ name: 'Find the HCF', make: round }];
  },
});

MathLab.app('chocolate-box', {
  emoji: '🍫',
  title: 'Chocolate Box',
  tagline: 'Turn the story into an expression. Then put a number in.',
  blurb: 'Word problems: write the expression first, then work out the number.',

  build() {
  const { rnd, pick, shuffle, mathHTML } = MathLab;

  /* Each story gives the right expression and the wrong ones people actually write.
     Offering the real mistakes as choices is the point: a blank box tells you nothing
     about which idea is broken, a chosen distractor tells you exactly. */

  function chocolates() {
    const N = pick([12, 16, 20, 24, 30]);
    return {
      story: 'There are <b>' + N + '</b> chocolates in a box. Aislin eats <i class="var">x</i> of them.',
      ask: 'Which expression says how many are <b>left</b>?',
      right: { text: N + ' − x', f: (x) => N - x },
      wrong: [
        { text: 'x − ' + N, f: (x) => x - N, why: 'That is the wrong way round — it gives a negative answer.' },
        { text: N + ' + x', f: (x) => N + x, why: 'Eating them makes the number go down, not up.' },
        { text: N + ' ÷ x', f: (x) => N / x, why: 'Nothing here is being shared out.' },
      ],
      value: rnd(3, 9),
      letter: 'x',
    };
  }

  function halfOfTheRest() {
    const N = pick([16, 20, 24, 28]);
    return {
      story: 'There are <b>' + N + '</b> chocolates. Aislin eats <i class="var">x</i>. ' +
             'Brindi then eats <b>half</b> of the ones that are left.',
      ask: 'Which expression says how many <b>Brindi</b> eats?',
      right: { text: '(' + N + ' − x) ÷ 2', f: (x) => (N - x) / 2 },
      wrong: [
        { text: N + ' − x ÷ 2', f: (x) => N - x / 2, why: 'Without the bracket, only the x gets halved.' },
        { text: N + ' ÷ 2 − x', f: (x) => N / 2 - x, why: 'That halves the box first, before Aislin eats.' },
        { text: '(' + N + ' + x) ÷ 2', f: (x) => (N + x) / 2, why: 'Aislin eating makes the pile smaller.' },
      ],
      value: pick([4, 8, 10, 14]).valueOf() <= N ? pick([4, 8, 10]) : 4,
      letter: 'x',
    };
  }

  function change() {
    const price = rnd(2, 6);
    const paid = pick([20, 50]);
    return {
      story: 'A bag of sweets costs <b>$' + price + '</b>. You buy <i class="var">n</i> bags ' +
             'and pay with a <b>$' + paid + '</b> note.',
      ask: 'Which expression says your <b>change</b>?',
      right: { text: paid + ' − ' + price + 'n', f: (n) => paid - price * n },
      wrong: [
        { text: price + 'n − ' + paid, f: (n) => price * n - paid, why: 'Wrong way round — the note is bigger than the bill.' },
        { text: paid + ' − ' + price + ' + n', f: (n) => paid - price + n, why: 'The price has to be multiplied by how many bags.' },
        { text: '(' + paid + ' − ' + price + ')n', f: (n) => (paid - price) * n, why: 'Only the bags are multiplied, not the change.' },
      ],
      value: rnd(2, 5),
      letter: 'n',
    };
  }

  function perimeter() {
    const less = rnd(2, 6);
    return {
      story: 'A rectangle is <i class="var">x</i> cm long. It is <b>' + less +
             ' cm shorter</b> than that across.',
      ask: 'Which expression says the <b>perimeter</b>?',
      right: { text: '4x − ' + 2 * less, f: (x) => 4 * x - 2 * less },
      wrong: [
        { text: '2x − ' + less, f: (x) => 2 * x - less, why: 'That is only one long side and one short side.' },
        { text: '4x − ' + less, f: (x) => 4 * x - less, why: 'There are two short sides, so the ' + less + ' comes off twice.' },
        { text: 'x(x − ' + less + ')', f: (x) => x * (x - less), why: 'That is the area, not the distance round.' },
      ],
      value: rnd(5, 12),
      letter: 'x',
    };
  }

  function sharing() {
    const N = pick([24, 30, 36, 40]);
    const left = rnd(2, 5);
    return {
      story: '<b>' + N + '</b> sweets are shared equally between <i class="var">n</i> friends. ' +
             '<b>' + left + '</b> sweets are left over.',
      ask: 'Which expression says how many each friend gets?',
      right: { text: '(' + N + ' − ' + left + ') ÷ n', f: (n) => (N - left) / n },
      wrong: [
        { text: N + ' ÷ n − ' + left, f: (n) => N / n - left, why: 'The leftovers come off the whole pile, before sharing.' },
        { text: N + ' ÷ n + ' + left, f: (n) => N / n + left, why: 'The leftovers are not given to anyone.' },
        { text: '(' + N + ' + ' + left + ') ÷ n', f: (n) => (N + left) / n, why: 'There are fewer to share, not more.' },
      ],
      value: pick([1, 2, 5, 7].filter((d) => (N - left) % d === 0)) || 1,
      letter: 'n',
    };
  }

  const STORIES = [chocolates, halfOfTheRest, change, perimeter, sharing];

  function round() {
    const s = pick(STORIES)();
    const options = shuffle([{ ...s.right, ok: true }, ...s.wrong.map((w) => ({ ...w, ok: false }))]);

    return {
      prompt: s.story,
      question: '',
      hint: 'Read it again one clause at a time, and write down what each clause does. ' +
            'If something happens to a whole amount, that amount needs a bracket round it.',
      solution: s.right.text,
      rightWhy: 'Each clause of the story became one part of the expression.',
      explain: '<ol><li>The expression is <b>' + mathHTML(s.right.text) + '</b>.</li>' +
        s.wrong.map((w) => '<li>Not ' + mathHTML(w.text) + ': ' + w.why + '</li>').join('') + '</ol>',

      mount(stage, submit) {
        let picked = null;

        stage.innerHTML = `
          <p class="piece-label" data-ask></p>
          <div class="options" data-options></div>
          <p class="why-line" data-why> </p>
        `;
        stage.querySelector('[data-ask]').innerHTML = s.ask;

        const box = stage.querySelector('[data-options]');
        const why = stage.querySelector('[data-why]');

        const buttons = options.map((opt) => {
          const b = document.createElement('button');
          b.type = 'button';
          b.className = 'option';
          b.innerHTML = mathHTML(opt.text);
          b.addEventListener('click', () => choose(opt, b));
          box.appendChild(b);
          return b;
        });

        function choose(opt, btn) {
          if (picked) return;
          picked = opt;

          buttons.forEach((b, i) => {
            b.disabled = true;
            if (options[i].ok) b.classList.add('hit');
            else if (b === btn) b.classList.add('miss');
          });

          why.className = 'why-line ' + (opt.ok ? 'good' : 'bad');
          why.innerHTML = opt.ok
            ? 'Yes — ' + mathHTML(s.right.text) + ' does each thing in the story, in order. Now put a number in.'
            : opt.why + ' The expression is <b>' + mathHTML(s.right.text) + '</b>.';

          askValue(opt.ok);
        }

        /* Second half: the expression is only useful if you can actually use it. */
        function askValue(cleanSoFar) {
          const want = s.right.f(s.value);

          const box2 = document.createElement('div');
          box2.className = 'banned';
          box2.innerHTML =
            '<b>Now use it</b><p>Work out the answer when <i class="var">' + s.letter +
            '</i> = <b>' + s.value + '</b>, using ' + mathHTML(s.right.text) + '.</p>' +
            '<div data-stage2></div>';
          stage.appendChild(box2);

          MathLab.textAnswer(box2.querySelector('[data-stage2]'), (ok) => {
            const line = document.createElement('p');
            line.className = 'why-line ' + (ok ? 'good' : 'bad');
            line.innerHTML = ok
              ? 'Correct — ' + s.right.text.replace(new RegExp(s.letter, 'g'), s.value) + ' = ' + want + '.'
              : 'It comes to <b>' + want + '</b>: ' +
                s.right.text.replace(new RegExp(s.letter, 'g'), s.value) + '.';
            box2.appendChild(line);

            const bridge = document.createElement('div');
            bridge.className = 'bridge';
            bridge.innerHTML =
              '<b>Written down</b><div class="written">' + mathHTML(s.right.text) +
              ',&nbsp; when ' + mathHTML(s.letter) + ' = ' + s.value + ' this is ' + want + '</div>';
            stage.appendChild(bridge);

            submit(ok && cleanSoFar);
          }, {
            placeholder: 'number',
            check: (raw) => {
              const n = Number(raw.replace(/[−–—]/g, '-').trim());
              return Number.isFinite(n) && Math.abs(n - want) < 1e-9;
            },
          });
        }
      },
    };
  }

  return [{ name: 'Word problems', make: round }];
  },
});
